INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-2-u3-X01','math',1,'u3',ARRAY['M1-2-u3-C1']::text[],'모양을 색깔이나 크기로 가른다 — 큰 네모와 작은 네모를 다른 모양이라고 함','같은 모양을 크기·색깔만 바꿔 나란히 놓고 생김새를 견주게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-2-u3-X02','math',1,'u3',ARRAY['M1-2-u3-C1']::text[],'굽은 선과 곧은 선을 보지 않고 물건 이름만 보고 모양을 정한다','테두리를 손가락으로 따라가며 꺾이는 곳이 있는지 확인시키기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-2-u3-X03','math',1,'u3',ARRAY['M1-2-u3-C1']::text[],'방향을 돌려 놓으면 다른 모양이라고 한다 — 눕힌 세모를 세모로 보지 못함','종이 모양 조각을 직접 돌려 보이며 뾰족한 곳 수가 그대로임을 세게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-2-u3-X04','math',1,'u3',ARRAY['M1-2-u3-C2']::text[],'뾰족한 곳의 수를 잘못 센다 — 세모를 4군데, 네모를 3군데라고 함','모양 조각의 꼭짓점에 스티커를 붙여 가며 세게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-2-u3-X05','math',1,'u3',ARRAY['M1-2-u3-C2']::text[],'곧은 선과 굽은 선을 구별하지 못한다 — 동그라미에도 곧은 선이 있다고 함','실이나 철사를 곧게·둥글게 만들어 보이며 두 선을 견주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-2-u3-X06','math',1,'u3',ARRAY['M1-2-u3-C3']::text[],'꾸미기 그림에서 겹치거나 작은 모양을 빠뜨리고 센다','센 모양에 연필로 표시하며 세는 습관 들이기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-2-u3-X07','math',1,'u3',ARRAY['M1-2-u3-C3']::text[],'같은 모양을 두 번 세어 실제보다 많게 답한다','왼쪽에서 오른쪽으로 차례를 정해 한 번씩만 세게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-2-u3-X08','math',1,'u3',ARRAY['M1-2-u3-C4','M1-2-u3-C5']::text[],'짧은바늘과 긴바늘의 역할을 바꾼다 — 긴바늘이 가리키는 수를 시로 읽음','짧은바늘만 남기고 가린 뒤 시를 읽게 한 다음 긴바늘을 보이기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-2-u3-X09','math',1,'u3',ARRAY['M1-2-u3-C5','M1-2-u3-C6']::text[],'몇 시 30분에서 짧은바늘이 가까운 다음 수를 시로 읽는다 — 3시 30분을 4시 30분이라 함','짧은바늘이 ‘지나온 수’를 읽는 것임을 손으로 짚으며 확인하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-2-u3-X10','math',1,'u3',ARRAY['M1-2-u3-C5']::text[],'긴바늘이 6을 가리키면 ‘6분’이라고 읽는다','긴바늘이 한 바퀴 도는 데 60분, 반 바퀴가 30분임을 시계 모형으로 돌려 보이기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-2-u3-X11','math',1,'u3',ARRAY['M1-2-u3-C6']::text[],'시계를 그릴 때 두 바늘의 길이를 바꿔 그린다','짧은바늘을 먼저 짧게 그리고 긴바늘을 덧그리는 순서로 연습시키기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L02_basic#1','math',1,2,'u3','L02','g1_2_math_u3_L02_basic','lesson_basic','M1-2-u3-C1',1,'mc','auto','그림을 보세요. 세모 모양은 몇 개인가요?',ARRAY['M1-2-u3-X07','M1-2-u3-X06']::text[],true,'{"seq":1,"concept":"M1-2-u3-C1","difficulty":1,"kind":"mc","stem":"그림을 보세요. 세모 모양은 몇 개인가요?","asset":{"type":"shape_row","shapes":["tri","cir","sq","tri","cir"]},"options":[{"t":"2","correct":true},{"t":"3","mis":"M1-2-u3-X07"},{"t":"1","mis":"M1-2-u3-X06"}],"explanation":["세모 모양만 골라 손으로 짚어 보세요.","세모는 2개예요.","센 것에 표시를 하면 두 번 세지 않아요."],"variant_rule":{"shapes":{"len":[4,6],"ask":"count","target":"tri"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L02_basic#2','math',1,2,'u3','L02','g1_2_math_u3_L02_basic','lesson_basic','M1-2-u3-C1',1,'sa','auto','그림을 보세요. 동그라미 모양은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M1-2-u3-C1","difficulty":1,"kind":"sa","stem":"그림을 보세요. 동그라미 모양은 몇 개인가요? 숫자로 쓰세요.","asset":{"type":"shape_row","shapes":["cir","sq","cir","tri","cir"]},"answer":["3"],"explanation":["동그라미만 골라 세어요.","동그라미는 3개예요.","네모와 세모는 세지 않아요."],"variant_rule":{"shapes":{"len":[4,6],"ask":"count","target":"cir"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L02_basic#3','math',1,2,'u3','L02','g1_2_math_u3_L02_basic','lesson_basic','M1-2-u3-C1',1,'mc','auto','🕐 시계는 어떤 모양인가요?',ARRAY['M1-2-u3-X02']::text[],false,'{"seq":3,"concept":"M1-2-u3-C1","difficulty":1,"kind":"mc","stem":"🕐 시계는 어떤 모양인가요?","options":[{"t":"동그라미 모양","correct":true},{"t":"네모 모양","mis":"M1-2-u3-X02"},{"t":"세모 모양","mis":"M1-2-u3-X02"}],"explanation":["시계의 테두리는 둥글게 이어져 있어요.","그래서 동그라미 모양이에요.","굽은 선으로 둘러싸인 모양이 동그라미예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L02_basic#4','math',1,2,'u3','L02','g1_2_math_u3_L02_basic','lesson_basic','M1-2-u3-C1',1,'sa','auto','점선으로 표시한 셋째 그림은 무슨 모양인가요?','{}'::text[],true,'{"seq":4,"concept":"M1-2-u3-C1","difficulty":1,"kind":"sa","stem":"점선으로 표시한 셋째 그림은 무슨 모양인가요?","asset":{"type":"shape_row","shapes":["tri","cir","sq","cir","tri"],"mark":3},"answer":["네모"],"explanation":["왼쪽에서 셋째 그림을 찾아요.","표시한 것은 네모 모양이에요.","모양 이름은 네모·세모·동그라미 셋이에요."],"variant_rule":{"shapes":{"len":[4,6],"ask":"which"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L02_basic#5','math',1,2,'u3','L02','g1_2_math_u3_L02_basic','lesson_basic','M1-2-u3-C1',2,'mc','auto','다음 가운데 네모 모양이 아닌 것은 무엇인가요?',ARRAY['M1-2-u3-X02']::text[],false,'{"seq":5,"concept":"M1-2-u3-C1","difficulty":2,"kind":"mc","stem":"다음 가운데 네모 모양이 아닌 것은 무엇인가요?","options":[{"t":"🍕 피자 한 조각","correct":true},{"t":"📗 공책","mis":"M1-2-u3-X02"},{"t":"🚪 문","mis":"M1-2-u3-X02"}],"explanation":["공책과 문은 곧은 선 네 개로 둘러싸여 있어요.","피자 한 조각은 뾰족한 곳이 세 군데인 세모 모양이에요.","먹는 것인지 아닌지가 아니라 생김새로 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L02_basic#6','math',1,2,'u3','L02','g1_2_math_u3_L02_basic','lesson_basic','M1-2-u3-C1',2,'ox','auto','동그라미 모양에는 뾰족한 곳이 있어요.',ARRAY['M1-2-u3-X05']::text[],false,'{"seq":6,"concept":"M1-2-u3-C1","difficulty":2,"kind":"ox","stem":"동그라미 모양에는 뾰족한 곳이 있어요.","reason_options":[{"t":"동그라미는 굽은 선으로만 이어져 있으니까","correct":true},{"t":"동그라미도 네 군데가 뾰족하니까","mis":"M1-2-u3-X05"}],"answer":"X","explanation":["동그라미를 손가락으로 따라가 보세요.","끝까지 부드럽게 이어져서 뾰족한 곳이 없어요.","뾰족한 곳은 곧은 선이 만나는 자리에 생겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L02_basic#7','math',1,2,'u3','L02','g1_2_math_u3_L02_basic','lesson_basic','M1-2-u3-C1',2,'mc','auto','삼각김밥을 비스듬히 눕혀 놓았어요. 이것은 무슨 모양인가요?',ARRAY['M1-2-u3-X03']::text[],false,'{"seq":7,"concept":"M1-2-u3-C1","difficulty":2,"kind":"mc","stem":"삼각김밥을 비스듬히 눕혀 놓았어요. 이것은 무슨 모양인가요?","options":[{"t":"세모 모양","correct":true},{"t":"네모 모양","mis":"M1-2-u3-X03"},{"t":"모양이 없어졌어요","mis":"M1-2-u3-X03"}],"explanation":["돌려 놓아도 뾰족한 곳은 그대로 세 군데예요.","그래서 여전히 세모 모양이에요.","모양은 방향을 바꿔도 달라지지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L02_basic#8','math',1,2,'u3','L02','g1_2_math_u3_L02_basic','lesson_basic','M1-2-u3-C1',2,'blank','auto','동전과 접시는 모두 (        ) 모양이에요.',ARRAY['M1-2-u3-X02']::text[],false,'{"seq":8,"concept":"M1-2-u3-C1","difficulty":2,"kind":"blank","stem":"동전과 접시는 모두 (        ) 모양이에요.","options":[{"t":"동그라미","correct":true},{"t":"네모","mis":"M1-2-u3-X02"},{"t":"세모","mis":"M1-2-u3-X02"}],"explanation":["동전과 접시의 테두리를 따라가 보세요.","둘 다 굽은 선으로 둥글게 이어져 동그라미 모양이에요.","크기가 달라도 모양 이름은 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L02_basic#9','math',1,2,'u3','L02','g1_2_math_u3_L02_basic','lesson_basic','M1-2-u3-C1',2,'match','auto','물건과 알맞은 모양을 줄로 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"M1-2-u3-C1","difficulty":2,"kind":"match","stem":"물건과 알맞은 모양을 줄로 이어 보세요.","pairs":[{"l":"📺 텔레비전","r":"네모 모양"},{"l":"🍕 피자 조각","r":"세모 모양"},{"l":"⏰ 시계","r":"동그라미 모양"}],"explanation":["물건의 테두리 생김새를 봐요.","텔레비전은 네모, 피자 조각은 세모, 시계는 동그라미예요.","색깔이나 크기는 모양과 상관이 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L02_basic#10','math',1,2,'u3','L02','g1_2_math_u3_L02_basic','lesson_basic','M1-2-u3-C1',3,'error','auto','네 친구가 네모 모양 물건을 하나씩 골랐어요. 잘못 고른 친구는 누구인가요?',ARRAY['M1-2-u3-X02']::text[],false,'{"seq":10,"concept":"M1-2-u3-C1","difficulty":3,"kind":"error","stem":"네 친구가 네모 모양 물건을 하나씩 골랐어요. 잘못 고른 친구는 누구인가요?","options":[{"t":"공을 고른 예나","correct":true,"mis_target":"M1-2-u3-X02"},{"t":"공책을 고른 준수","mis":"M1-2-u3-X02"},{"t":"창문을 고른 서아","mis":"M1-2-u3-X02"}],"explanation":["공책과 창문은 곧은 선 네 개로 둘러싸여 있어요.","공은 굽은 선으로 이어진 동그라미 모양이에요.","네모인지 볼 때는 뾰족한 곳이 네 군데인지 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L02_challenge#1','math',1,2,'u3','L02','g1_2_math_u3_L02_challenge','lesson_challenge','M1-2-u3-C1',2,'mc','auto','그림을 보세요. 네모 모양은 몇 개인가요?',ARRAY['M1-2-u3-X06','M1-2-u3-X07']::text[],true,'{"seq":1,"concept":"M1-2-u3-C1","difficulty":2,"kind":"mc","stem":"그림을 보세요. 네모 모양은 몇 개인가요?","asset":{"type":"shape_row","shapes":["sq","tri","sq","cir","sq","tri"]},"options":[{"t":"3","correct":true},{"t":"2","mis":"M1-2-u3-X06"},{"t":"4","mis":"M1-2-u3-X07"}],"explanation":["네모만 골라 하나씩 짚어요.","네모는 3개예요.","센 것에 표시하면 빠뜨리지 않아요."],"variant_rule":{"shapes":{"len":[4,6],"ask":"count","target":"sq"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L02_challenge#2','math',1,2,'u3','L02','g1_2_math_u3_L02_challenge','lesson_challenge','M1-2-u3-C1',2,'sa','auto','점선으로 표시한 다섯째 그림은 무슨 모양인가요?','{}'::text[],true,'{"seq":2,"concept":"M1-2-u3-C1","difficulty":2,"kind":"sa","stem":"점선으로 표시한 다섯째 그림은 무슨 모양인가요?","asset":{"type":"shape_row","shapes":["sq","tri","sq","tri","cir","sq"],"mark":5},"answer":["동그라미"],"explanation":["왼쪽에서 다섯째 그림을 찾아요.","표시한 것은 동그라미 모양이에요.","표시가 어디에 있는지 먼저 확인해요."],"variant_rule":{"shapes":{"len":[4,6],"ask":"which"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L02_challenge#3','math',1,2,'u3','L02','g1_2_math_u3_L02_challenge','lesson_challenge','M1-2-u3-C1',3,'mc','auto','같은 모양끼리 모은 것 가운데 잘못된 것은 무엇인가요?',ARRAY['M1-2-u3-X02']::text[],false,'{"seq":3,"concept":"M1-2-u3-C1","difficulty":3,"kind":"mc","stem":"같은 모양끼리 모은 것 가운데 잘못된 것은 무엇인가요?","options":[{"t":"🪟 창문, ⚽ 축구공, 📕 책","correct":true},{"t":"🍕 피자 조각, ⛺ 텐트, 🚩 깃발","mis":"M1-2-u3-X02"},{"t":"🪙 동전, ⏰ 시계, 🍩 도넛","mis":"M1-2-u3-X02"}],"explanation":["둘째 묶음은 모두 세모, 셋째 묶음은 모두 동그라미예요.","첫째 묶음의 축구공만 동그라미라서 섞였어요.","한 묶음 안의 물건을 하나씩 견줘 보세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L02_challenge#4','math',1,2,'u3','L02','g1_2_math_u3_L02_challenge','lesson_challenge','M1-2-u3-C1',3,'ox','auto','큰 네모와 작은 네모는 서로 다른 모양이에요.',ARRAY['M1-2-u3-X01']::text[],false,'{"seq":4,"concept":"M1-2-u3-C1","difficulty":3,"kind":"ox","stem":"큰 네모와 작은 네모는 서로 다른 모양이에요.","reason_options":[{"t":"크기가 달라도 생김새가 같으면 같은 모양이니까","correct":true},{"t":"크기가 다르면 이름도 달라지니까","mis":"M1-2-u3-X01"}],"answer":"X","explanation":["모양은 생김새로 정해요.","크기가 달라도 둘 다 네모 모양이에요.","색깔이 달라도 마찬가지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L02_challenge#5','math',1,2,'u3','L02','g1_2_math_u3_L02_challenge','lesson_challenge','M1-2-u3-C1',3,'error','auto','동그라미 모양만 모으기로 했어요. 잘못 들어온 것은 무엇인가요?',ARRAY['M1-2-u3-X02']::text[],false,'{"seq":5,"concept":"M1-2-u3-C1","difficulty":3,"kind":"error","stem":"동그라미 모양만 모으기로 했어요. 잘못 들어온 것은 무엇인가요?","options":[{"t":"🚩 깃발","correct":true,"mis_target":"M1-2-u3-X02"},{"t":"🪙 동전","mis":"M1-2-u3-X02"},{"t":"🍩 도넛","mis":"M1-2-u3-X02"}],"explanation":["동전과 도넛은 굽은 선으로 둥글게 이어져 있어요.","깃발은 뾰족한 곳이 있는 세모 모양이에요.","굽은 선인지 곧은 선인지를 먼저 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L02_challenge#6','math',1,2,'u3','L02','g1_2_math_u3_L02_challenge','lesson_challenge','M1-2-u3-C1',3,'sa','auto','그림에 쓴 세모 모양은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M1-2-u3-C1","difficulty":3,"kind":"sa","stem":"그림에 쓴 세모 모양은 몇 개인가요? 숫자로 쓰세요.","asset":{"type":"shape_art","parts":[{"shape":"sq","n":3},{"shape":"tri","n":4},{"shape":"cir","n":2}],"name":"돛단배"},"answer":["4"],"explanation":["세모만 골라 하나씩 표시하며 세어요.","세모는 4개예요.","섞여 있을 때는 한 종류씩 차례로 세요."],"variant_rule":{"art":{"n":[2,5],"ask":"tri"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L02_challenge#7','math',1,2,'u3','L02','g1_2_math_u3_L02_challenge','lesson_challenge','M1-2-u3-C1',3,'mc','auto','굽은 선으로만 둘러싸인 모양은 무엇인가요?',ARRAY['M1-2-u3-X05']::text[],false,'{"seq":7,"concept":"M1-2-u3-C1","difficulty":3,"kind":"mc","stem":"굽은 선으로만 둘러싸인 모양은 무엇인가요?","options":[{"t":"동그라미 모양","correct":true},{"t":"네모 모양","mis":"M1-2-u3-X05"},{"t":"세모 모양","mis":"M1-2-u3-X05"}],"explanation":["네모와 세모는 곧은 선으로 둘러싸여 있어요.","동그라미만 굽은 선으로 이어져 있어요.","손가락으로 테두리를 따라가면 알 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L02_challenge#8','math',1,2,'u3','L02','g1_2_math_u3_L02_challenge','lesson_challenge','M1-2-u3-C1',4,'essay','teacher','우리 교실에서 동그라미 모양 물건을 하나 찾아 쓰고, 왜 동그라미 모양인지 까닭도 함께 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M1-2-u3-C1","difficulty":4,"kind":"essay","stem":"우리 교실에서 동그라미 모양 물건을 하나 찾아 쓰고, 왜 동그라미 모양인지 까닭도 함께 쓰세요.","answer_guide":"물건 이름 + 까닭(테두리가 굽은 선으로 둥글게 이어져 있다 / 뾰족한 곳이 없다)을 함께 쓰면 정답. 물건 이름만 쓰면 반만 맞음.","explanation":["교실을 둘러보며 둥근 물건을 찾아요.","시계·동전·컵 바닥 같은 것이 있어요.","까닭에는 굽은 선이나 뾰족한 곳 이야기가 들어가야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L02_challenge#9','math',1,2,'u3','L02','g1_2_math_u3_L02_challenge','lesson_challenge','M1-2-u3-C1',4,'mc','auto','뾰족한 곳이 네 군데이고 곧은 선이 네 개인 모양은 무엇인가요?',ARRAY['M1-2-u3-X04','M1-2-u3-X05']::text[],false,'{"seq":9,"concept":"M1-2-u3-C1","difficulty":4,"kind":"mc","stem":"뾰족한 곳이 네 군데이고 곧은 선이 네 개인 모양은 무엇인가요?","options":[{"t":"네모 모양","correct":true},{"t":"세모 모양","mis":"M1-2-u3-X04"},{"t":"동그라미 모양","mis":"M1-2-u3-X05"}],"explanation":["세모는 뾰족한 곳이 세 군데예요.","뾰족한 곳과 곧은 선이 각각 네 개인 것은 네모예요.","동그라미는 곧은 선이 하나도 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L02_challenge#10','math',1,2,'u3','L02','g1_2_math_u3_L02_challenge','lesson_challenge','M1-2-u3-C1',4,'sa','auto','그림을 보세요. 뾰족한 곳이 세 군데인 모양은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M1-2-u3-C1","difficulty":4,"kind":"sa","stem":"그림을 보세요. 뾰족한 곳이 세 군데인 모양은 몇 개인가요? 숫자로 쓰세요.","asset":{"type":"shape_row","shapes":["tri","sq","tri","cir","tri","sq"]},"answer":["3"],"explanation":["뾰족한 곳이 세 군데인 모양은 세모예요.","세모를 세어 보면 3개예요.","묻는 것이 어떤 모양인지 먼저 알아내야 해요."],"variant_rule":{"shapes":{"len":[4,6],"ask":"count","target":"tri"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L03_basic#1','math',1,2,'u3','L03','g1_2_math_u3_L03_basic','lesson_basic','M1-2-u3-C2',1,'mc','auto','세모 모양은 뾰족한 곳이 몇 군데인가요?',ARRAY['M1-2-u3-X04','M1-2-u3-X05']::text[],false,'{"seq":1,"concept":"M1-2-u3-C2","difficulty":1,"kind":"mc","stem":"세모 모양은 뾰족한 곳이 몇 군데인가요?","options":[{"t":"3군데","correct":true},{"t":"4군데","mis":"M1-2-u3-X04"},{"t":"뾰족한 곳이 없어요","mis":"M1-2-u3-X05"}],"explanation":["세모의 뾰족한 곳을 손으로 짚어 보세요.","세 군데예요.","곧은 선 두 개가 만나는 자리가 뾰족한 곳이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L03_basic#2','math',1,2,'u3','L03','g1_2_math_u3_L03_basic','lesson_basic','M1-2-u3-C2',1,'sa','auto','네모 모양은 곧은 선이 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"M1-2-u3-C2","difficulty":1,"kind":"sa","stem":"네모 모양은 곧은 선이 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["네모의 테두리를 따라가며 선을 세어요.","곧은 선이 4개예요.","뾰족한 곳도 4군데예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L03_basic#3','math',1,2,'u3','L03','g1_2_math_u3_L03_basic','lesson_basic','M1-2-u3-C2',1,'mc','auto','굽은 선이 있는 모양은 무엇인가요?',ARRAY['M1-2-u3-X05']::text[],false,'{"seq":3,"concept":"M1-2-u3-C2","difficulty":1,"kind":"mc","stem":"굽은 선이 있는 모양은 무엇인가요?","options":[{"t":"동그라미 모양","correct":true},{"t":"세모 모양","mis":"M1-2-u3-X05"},{"t":"네모 모양","mis":"M1-2-u3-X05"}],"explanation":["세모와 네모는 곧은 선으로만 되어 있어요.","동그라미만 굽은 선으로 이어져 있어요.","선을 따라가며 꺾이는지 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L03_basic#4','math',1,2,'u3','L03','g1_2_math_u3_L03_basic','lesson_basic','M1-2-u3-C2',1,'mc','auto','점선으로 표시한 둘째 그림은 뾰족한 곳이 몇 군데인가요?',ARRAY['M1-2-u3-X04','M1-2-u3-X05']::text[],false,'{"seq":4,"concept":"M1-2-u3-C2","difficulty":1,"kind":"mc","stem":"점선으로 표시한 둘째 그림은 뾰족한 곳이 몇 군데인가요?","asset":{"type":"shape_row","shapes":["cir","sq","tri","cir"],"mark":2},"options":[{"t":"4군데","correct":true},{"t":"3군데","mis":"M1-2-u3-X04"},{"t":"없어요","mis":"M1-2-u3-X05"}],"explanation":["표시한 것은 네모 모양이에요.","네모의 뾰족한 곳은 네 군데예요.","모양을 먼저 알아낸 다음 세어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L03_basic#5','math',1,2,'u3','L03','g1_2_math_u3_L03_basic','lesson_basic','M1-2-u3-C2',2,'ox','auto','네모 모양과 세모 모양은 모두 곧은 선으로 둘러싸여 있어요.',ARRAY['M1-2-u3-X05']::text[],false,'{"seq":5,"concept":"M1-2-u3-C2","difficulty":2,"kind":"ox","stem":"네모 모양과 세모 모양은 모두 곧은 선으로 둘러싸여 있어요.","reason_options":[{"t":"둘 다 굽은 선 없이 곧은 선만 있으니까","correct":true},{"t":"네모에는 굽은 선도 하나 있으니까","mis":"M1-2-u3-X05"}],"answer":"O","explanation":["네모는 곧은 선 4개, 세모는 곧은 선 3개예요.","둘 다 굽은 선이 없어요.","굽은 선이 있는 것은 동그라미뿐이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L03_basic#6','math',1,2,'u3','L03','g1_2_math_u3_L03_basic','lesson_basic','M1-2-u3-C2',2,'match','auto','모양과 알맞은 설명을 줄로 이어 보세요.','{}'::text[],false,'{"seq":6,"concept":"M1-2-u3-C2","difficulty":2,"kind":"match","stem":"모양과 알맞은 설명을 줄로 이어 보세요.","pairs":[{"l":"세모 모양","r":"뾰족한 곳이 3군데"},{"l":"네모 모양","r":"뾰족한 곳이 4군데"},{"l":"동그라미 모양","r":"뾰족한 곳이 없어요"}],"explanation":["뾰족한 곳의 수로 모양을 구별할 수 있어요.","세모 3군데, 네모 4군데, 동그라미는 없어요.","설명을 읽고 손으로 모양을 그려 보세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
