INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L03_basic#8','math',1,2,'u3','L03','g1_2_math_u3_L03_basic','lesson_basic','M1-2-u3-C2',2,'sa','auto','동그라미 모양은 뾰족한 곳이 몇 군데인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M1-2-u3-C2","difficulty":2,"kind":"sa","stem":"동그라미 모양은 뾰족한 곳이 몇 군데인가요? 숫자로 쓰세요.","answer":["0","없어요","없다"],"explanation":["동그라미 테두리를 손으로 따라가 보세요.","꺾이는 곳이 없어서 뾰족한 곳은 0군데예요.","굽은 선은 꺾이지 않고 이어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L03_basic#9','math',1,2,'u3','L03','g1_2_math_u3_L03_basic','lesson_basic','M1-2-u3-C2',2,'blank','auto','책상 위 (        ) 모양은 곧은 선 네 개로 둘러싸여 있어요.',ARRAY['M1-2-u3-X04','M1-2-u3-X05']::text[],false,'{"seq":9,"concept":"M1-2-u3-C2","difficulty":2,"kind":"blank","stem":"책상 위 (        ) 모양은 곧은 선 네 개로 둘러싸여 있어요.","options":[{"t":"네모","correct":true},{"t":"세모","mis":"M1-2-u3-X04"},{"t":"동그라미","mis":"M1-2-u3-X05"}],"explanation":["곧은 선이 네 개인 모양을 떠올려요.","네모 모양이에요.","세모는 세 개, 동그라미는 곧은 선이 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L03_basic#10','math',1,2,'u3','L03','g1_2_math_u3_L03_basic','lesson_basic','M1-2-u3-C2',3,'error','auto','친구가 세모 모양을 이렇게 설명했어요. 잘못된 설명은 무엇인가요?',ARRAY['M1-2-u3-X04','M1-2-u3-X05']::text[],false,'{"seq":10,"concept":"M1-2-u3-C2","difficulty":3,"kind":"error","stem":"친구가 세모 모양을 이렇게 설명했어요. 잘못된 설명은 무엇인가요?","options":[{"t":"뾰족한 곳이 4군데예요.","correct":true,"mis_target":"M1-2-u3-X04"},{"t":"곧은 선이 3개예요.","mis":"M1-2-u3-X04"},{"t":"굽은 선이 없어요.","mis":"M1-2-u3-X05"}],"explanation":["세모의 뾰족한 곳은 세 군데예요.","4군데라고 한 설명이 잘못됐어요.","곧은 선 3개, 굽은 선 없음은 맞는 설명이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L03_challenge#1','math',1,2,'u3','L03','g1_2_math_u3_L03_challenge','lesson_challenge','M1-2-u3-C2',2,'mc','auto','뾰족한 곳이 없는 모양은 몇 개인가요?',ARRAY['M1-2-u3-X07','M1-2-u3-X06']::text[],true,'{"seq":1,"concept":"M1-2-u3-C2","difficulty":2,"kind":"mc","stem":"뾰족한 곳이 없는 모양은 몇 개인가요?","asset":{"type":"shape_row","shapes":["cir","sq","tri","cir","sq"]},"options":[{"t":"2","correct":true},{"t":"3","mis":"M1-2-u3-X07"},{"t":"1","mis":"M1-2-u3-X06"}],"explanation":["뾰족한 곳이 없는 모양은 동그라미예요.","동그라미는 2개예요.","묻는 것이 어떤 모양인지 먼저 알아내요."],"variant_rule":{"shapes":{"len":[4,6],"ask":"count","target":"cir"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L03_challenge#2','math',1,2,'u3','L03','g1_2_math_u3_L03_challenge','lesson_challenge','M1-2-u3-C2',2,'sa','auto','네모 모양의 곧은 선 수와 세모 모양의 곧은 선 수를 더하면 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"M1-2-u3-C2","difficulty":2,"kind":"sa","stem":"네모 모양의 곧은 선 수와 세모 모양의 곧은 선 수를 더하면 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["네모는 곧은 선이 4개예요.","세모는 3개라서 4 + 3 = 7이에요.","두 모양의 선을 따로 세고 더해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
