INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L03_challenge#4','math',1,2,'u3','L03','g1_2_math_u3_L03_challenge','lesson_challenge','M1-2-u3-C2',3,'ox','auto','뾰족한 곳의 수를 세면 세모와 네모를 구별할 수 있어요.',ARRAY['M1-2-u3-X04']::text[],false,'{"seq":4,"concept":"M1-2-u3-C2","difficulty":3,"kind":"ox","stem":"뾰족한 곳의 수를 세면 세모와 네모를 구별할 수 있어요.","reason_options":[{"t":"세모는 3군데, 네모는 4군데로 수가 다르니까","correct":true},{"t":"두 모양 모두 뾰족한 곳이 4군데니까","mis":"M1-2-u3-X04"}],"answer":"O","explanation":["세모의 뾰족한 곳은 3군데예요.","네모는 4군데라서 수로 구별할 수 있어요.","크기나 색깔로는 구별할 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L03_challenge#5','math',1,2,'u3','L03','g1_2_math_u3_L03_challenge','lesson_challenge','M1-2-u3-C2',3,'error','auto','네모 모양을 설명한 것 가운데 잘못된 것은 무엇인가요?',ARRAY['M1-2-u3-X05','M1-2-u3-X04']::text[],false,'{"seq":5,"concept":"M1-2-u3-C2","difficulty":3,"kind":"error","stem":"네모 모양을 설명한 것 가운데 잘못된 것은 무엇인가요?","options":[{"t":"굽은 선이 하나 있어요.","correct":true,"mis_target":"M1-2-u3-X05"},{"t":"곧은 선이 4개예요.","mis":"M1-2-u3-X04"},{"t":"뾰족한 곳이 4군데예요.","mis":"M1-2-u3-X04"}],"explanation":["네모는 곧은 선 4개, 뾰족한 곳 4군데예요.","굽은 선은 하나도 없어요.","굽은 선이 있는 모양은 동그라미뿐이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L03_challenge#6','math',1,2,'u3','L03','g1_2_math_u3_L03_challenge','lesson_challenge','M1-2-u3-C2',3,'mc','auto','세모 모양과 네모 모양의 같은 점은 무엇인가요?',ARRAY['M1-2-u3-X04','M1-2-u3-X05']::text[],false,'{"seq":6,"concept":"M1-2-u3-C2","difficulty":3,"kind":"mc","stem":"세모 모양과 네모 모양의 같은 점은 무엇인가요?","options":[{"t":"둘 다 곧은 선으로 둘러싸여 있어요.","correct":true},{"t":"둘 다 뾰족한 곳이 4군데예요.","mis":"M1-2-u3-X04"},{"t":"둘 다 굽은 선이 있어요.","mis":"M1-2-u3-X05"}],"explanation":["세모는 곧은 선 3개, 네모는 4개예요.","수는 다르지만 둘 다 곧은 선으로만 되어 있어요.","굽은 선이 있는 것은 동그라미예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L03_challenge#7','math',1,2,'u3','L03','g1_2_math_u3_L03_challenge','lesson_challenge','M1-2-u3-C2',3,'sa','auto','그림에서 곧은 선으로 둘러싸인 모양은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"M1-2-u3-C2","difficulty":3,"kind":"sa","stem":"그림에서 곧은 선으로 둘러싸인 모양은 모두 몇 개인가요? 숫자로 쓰세요.","asset":{"type":"shape_row","shapes":["sq","cir","tri","sq","tri","cir"]},"answer":["4"],"explanation":["곧은 선으로 둘러싸인 모양은 네모와 세모예요.","네모 2개와 세모 2개를 더하면 4개예요.","동그라미는 세지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L03_challenge#8','math',1,2,'u3','L03','g1_2_math_u3_L03_challenge','lesson_challenge','M1-2-u3-C2',4,'essay','teacher','동그라미 모양과 네모 모양의 다른 점을 한 가지 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M1-2-u3-C2","difficulty":4,"kind":"essay","stem":"동그라미 모양과 네모 모양의 다른 점을 한 가지 쓰세요.","answer_guide":"‘동그라미는 굽은 선, 네모는 곧은 선’ 또는 ‘동그라미는 뾰족한 곳이 없고 네모는 4군데’ 같이 선이나 뾰족한 곳을 근거로 들면 정답. ‘크기가 다르다’는 답은 오답.","explanation":["두 모양의 테두리를 따라가 보세요.","선의 종류나 뾰족한 곳의 수로 견주면 돼요.","크기와 색깔은 모양의 차이가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L03_challenge#9','math',1,2,'u3','L03','g1_2_math_u3_L03_challenge','lesson_challenge','M1-2-u3-C2',4,'mc','auto','뾰족한 곳의 수가 가장 많은 모양부터 차례로 놓은 것은 무엇인가요?',ARRAY['M1-2-u3-X04','M1-2-u3-X05']::text[],false,'{"seq":9,"concept":"M1-2-u3-C2","difficulty":4,"kind":"mc","stem":"뾰족한 곳의 수가 가장 많은 모양부터 차례로 놓은 것은 무엇인가요?","options":[{"t":"네모 - 세모 - 동그라미","correct":true},{"t":"세모 - 네모 - 동그라미","mis":"M1-2-u3-X04"},{"t":"동그라미 - 네모 - 세모","mis":"M1-2-u3-X05"}],"explanation":["네모 4군데, 세모 3군데, 동그라미 0군데예요.","많은 것부터 놓으면 네모 - 세모 - 동그라미예요.","동그라미는 뾰족한 곳이 없어 맨 뒤예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L03_challenge#10','math',1,2,'u3','L03','g1_2_math_u3_L03_challenge','lesson_challenge','M1-2-u3-C2',4,'sa','auto','나는 곧은 선이 3개이고 뾰족한 곳도 3군데예요. 나는 무슨 모양인가요?','{}'::text[],false,'{"seq":10,"concept":"M1-2-u3-C2","difficulty":4,"kind":"sa","stem":"나는 곧은 선이 3개이고 뾰족한 곳도 3군데예요. 나는 무슨 모양인가요?","answer":["세모","세모 모양"],"explanation":["곧은 선과 뾰족한 곳이 각각 3개예요.","그런 모양은 세모예요.","수를 하나씩 견주며 모양을 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L04_basic#1','math',1,2,'u3','L04','g1_2_math_u3_L04_basic','lesson_basic','M1-2-u3-C3',1,'mc','auto','로봇 그림에 쓴 네모 모양은 몇 개인가요?',ARRAY['M1-2-u3-X06','M1-2-u3-X07']::text[],true,'{"seq":1,"concept":"M1-2-u3-C3","difficulty":1,"kind":"mc","stem":"로봇 그림에 쓴 네모 모양은 몇 개인가요?","asset":{"type":"shape_art","parts":[{"shape":"sq","n":4},{"shape":"tri","n":2},{"shape":"cir","n":3}],"name":"로봇"},"options":[{"t":"4","correct":true},{"t":"3","mis":"M1-2-u3-X06"},{"t":"5","mis":"M1-2-u3-X07"}],"explanation":["네모만 골라 하나씩 짚어요.","네모는 4개예요.","센 것에 표시하면 두 번 세지 않아요."],"variant_rule":{"art":{"n":[2,5],"ask":"sq"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L04_basic#2','math',1,2,'u3','L04','g1_2_math_u3_L04_basic','lesson_basic','M1-2-u3-C3',1,'sa','auto','로봇 그림에 쓴 동그라미 모양은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M1-2-u3-C3","difficulty":1,"kind":"sa","stem":"로봇 그림에 쓴 동그라미 모양은 몇 개인가요? 숫자로 쓰세요.","asset":{"type":"shape_art","parts":[{"shape":"sq","n":4},{"shape":"tri","n":2},{"shape":"cir","n":3}],"name":"로봇"},"answer":["3"],"explanation":["동그라미만 골라 세어요.","동그라미는 3개예요.","다른 모양은 세지 않아요."],"variant_rule":{"art":{"n":[2,5],"ask":"cir"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L04_basic#3','math',1,2,'u3','L04','g1_2_math_u3_L04_basic','lesson_basic','M1-2-u3-C3',1,'mc','auto','돛단배 그림에 쓴 세모 모양은 몇 개인가요?',ARRAY['M1-2-u3-X06','M1-2-u3-X07']::text[],true,'{"seq":3,"concept":"M1-2-u3-C3","difficulty":1,"kind":"mc","stem":"돛단배 그림에 쓴 세모 모양은 몇 개인가요?","asset":{"type":"shape_art","parts":[{"shape":"sq","n":2},{"shape":"tri","n":3},{"shape":"cir","n":2}],"name":"돛단배"},"options":[{"t":"3","correct":true},{"t":"2","mis":"M1-2-u3-X06"},{"t":"4","mis":"M1-2-u3-X07"}],"explanation":["세모만 골라 표시하며 세어요.","세모는 3개예요.","모양 하나에 표시 하나씩 해요."],"variant_rule":{"art":{"n":[2,5],"ask":"tri"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L04_basic#4','math',1,2,'u3','L04','g1_2_math_u3_L04_basic','lesson_basic','M1-2-u3-C3',1,'sa','auto','돛단배 그림에 쓴 모양은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M1-2-u3-C3","difficulty":1,"kind":"sa","stem":"돛단배 그림에 쓴 모양은 모두 몇 개인가요? 숫자로 쓰세요.","asset":{"type":"shape_art","parts":[{"shape":"sq","n":2},{"shape":"tri","n":3},{"shape":"cir","n":2}],"name":"돛단배"},"answer":["7"],"explanation":["종류별로 세어요 — 네모 2개, 세모 3개, 동그라미 2개.","모두 더하면 7개예요.","한 종류씩 세고 더하면 빠뜨리지 않아요."],"variant_rule":{"art":{"n":[2,5],"ask":"total"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L04_basic#5','math',1,2,'u3','L04','g1_2_math_u3_L04_basic','lesson_basic','M1-2-u3-C3',2,'mc','auto','기차 그림에서 가장 많이 쓴 모양은 무엇인가요?',ARRAY['M1-2-u3-X06']::text[],false,'{"seq":5,"concept":"M1-2-u3-C3","difficulty":2,"kind":"mc","stem":"기차 그림에서 가장 많이 쓴 모양은 무엇인가요?","asset":{"type":"shape_art","parts":[{"shape":"sq","n":5},{"shape":"tri","n":2},{"shape":"cir","n":3}],"name":"기차"},"options":[{"t":"네모 모양","correct":true},{"t":"동그라미 모양","mis":"M1-2-u3-X06"},{"t":"세모 모양","mis":"M1-2-u3-X06"}],"explanation":["네모 5개, 동그라미 3개, 세모 2개예요.","가장 많은 것은 네모 모양이에요.","종류별로 센 다음 수를 견줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L04_basic#6','math',1,2,'u3','L04','g1_2_math_u3_L04_basic','lesson_basic','M1-2-u3-C3',2,'sa','auto','집 그림에서 네모 모양과 세모 모양의 수를 더하면 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"M1-2-u3-C3","difficulty":2,"kind":"sa","stem":"집 그림에서 네모 모양과 세모 모양의 수를 더하면 몇 개인가요? 숫자로 쓰세요.","asset":{"type":"shape_art","parts":[{"shape":"sq","n":4},{"shape":"tri","n":3},{"shape":"cir","n":2}],"name":"집"},"answer":["7"],"explanation":["네모는 4개, 세모는 3개예요.","4 + 3 = 7개예요.","동그라미는 더하지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L04_basic#7','math',1,2,'u3','L04','g1_2_math_u3_L04_basic','lesson_basic','M1-2-u3-C3',2,'ox','auto','꾸미기 그림에서 모양을 셀 때는 색깔이 같은 것만 세어야 해요.',ARRAY['M1-2-u3-X06']::text[],false,'{"seq":7,"concept":"M1-2-u3-C3","difficulty":2,"kind":"ox","stem":"꾸미기 그림에서 모양을 셀 때는 색깔이 같은 것만 세어야 해요.","reason_options":[{"t":"색깔이 달라도 생김새가 같으면 같은 모양이니까","correct":true},{"t":"색깔이 다르면 다른 모양이니까","mis":"M1-2-u3-X06"}],"answer":"X","explanation":["모양은 생김새로 정해요.","색깔이 달라도 네모는 네모예요.","셀 때는 생김새만 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L04_basic#8','math',1,2,'u3','L04','g1_2_math_u3_L04_basic','lesson_basic','M1-2-u3-C3',2,'mc','auto','나비 그림에 쓴 동그라미 모양은 몇 개인가요?',ARRAY['M1-2-u3-X06','M1-2-u3-X07']::text[],true,'{"seq":8,"concept":"M1-2-u3-C3","difficulty":2,"kind":"mc","stem":"나비 그림에 쓴 동그라미 모양은 몇 개인가요?","asset":{"type":"shape_art","parts":[{"shape":"sq","n":2},{"shape":"tri","n":3},{"shape":"cir","n":4}],"name":"나비"},"options":[{"t":"4","correct":true},{"t":"3","mis":"M1-2-u3-X06"},{"t":"5","mis":"M1-2-u3-X07"}],"explanation":["동그라미만 골라 하나씩 세어요.","동그라미는 4개예요.","세모와 네모는 세지 않아요."],"variant_rule":{"art":{"n":[2,5],"ask":"cir"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L04_basic#9','math',1,2,'u3','L04','g1_2_math_u3_L04_basic','lesson_basic','M1-2-u3-C3',2,'blank','auto','세모 3개, 네모 2개로 꾸민 그림에는 모양이 모두 (        ) 개 있어요.',ARRAY['M1-2-u3-X06','M1-2-u3-X07']::text[],false,'{"seq":9,"concept":"M1-2-u3-C3","difficulty":2,"kind":"blank","stem":"세모 3개, 네모 2개로 꾸민 그림에는 모양이 모두 (        ) 개 있어요.","options":[{"t":"5","correct":true},{"t":"3","mis":"M1-2-u3-X06"},{"t":"6","mis":"M1-2-u3-X07"}],"explanation":["세모 3개와 네모 2개를 더해요.","3 + 2 = 5개예요.","한 종류만 세면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L04_basic#10','math',1,2,'u3','L04','g1_2_math_u3_L04_basic','lesson_basic','M1-2-u3-C3',3,'error','auto','친구가 그림의 네모를 세어 보고 5개라고 했어요. 왜 틀렸을까요?',ARRAY['M1-2-u3-X06','M1-2-u3-X07']::text[],false,'{"seq":10,"concept":"M1-2-u3-C3","difficulty":3,"kind":"error","stem":"친구가 그림의 네모를 세어 보고 5개라고 했어요. 왜 틀렸을까요?","asset":{"type":"shape_art","parts":[{"shape":"sq","n":6},{"shape":"tri","n":2},{"shape":"cir","n":2}],"name":"성"},"options":[{"t":"겹쳐 놓인 네모 하나를 빠뜨리고 세었어요.","correct":true,"mis_target":"M1-2-u3-X06"},{"t":"네모는 셀 수 없는 모양이니까요.","mis":"M1-2-u3-X07"},{"t":"색깔이 다른 네모는 세면 안 되니까요.","mis":"M1-2-u3-X06"}],"explanation":["그림에는 네모가 6개 있어요.","겹친 곳에 숨은 네모를 빠뜨려서 5개가 되었어요.","센 모양에 표시를 하면 빠뜨리지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L04_challenge#1','math',1,2,'u3','L04','g1_2_math_u3_L04_challenge','lesson_challenge','M1-2-u3-C3',2,'mc','auto','그림에 쓴 모양은 모두 몇 개인가요?',ARRAY['M1-2-u3-X06','M1-2-u3-X07']::text[],true,'{"seq":1,"concept":"M1-2-u3-C3","difficulty":2,"kind":"mc","stem":"그림에 쓴 모양은 모두 몇 개인가요?","asset":{"type":"shape_art","parts":[{"shape":"sq","n":5},{"shape":"tri","n":3},{"shape":"cir","n":3}],"name":"성"},"options":[{"t":"11","correct":true},{"t":"5","mis":"M1-2-u3-X06"},{"t":"12","mis":"M1-2-u3-X07"}],"explanation":["네모 5개, 세모 3개, 동그라미 3개예요.","모두 더하면 11개예요.","한 종류만 세면 답이 아니에요."],"variant_rule":{"art":{"n":[2,5],"ask":"total"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L04_challenge#2','math',1,2,'u3','L04','g1_2_math_u3_L04_challenge','lesson_challenge','M1-2-u3-C3',2,'sa','auto','그림에서 세모 모양은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M1-2-u3-C3","difficulty":2,"kind":"sa","stem":"그림에서 세모 모양은 몇 개인가요? 숫자로 쓰세요.","asset":{"type":"shape_art","parts":[{"shape":"sq","n":3},{"shape":"tri","n":4},{"shape":"cir","n":3}],"name":"숲"},"answer":["4"],"explanation":["세모만 골라 표시하며 세어요.","세모는 4개예요.","표시를 하면 두 번 세지 않아요."],"variant_rule":{"art":{"n":[2,5],"ask":"tri"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L04_challenge#3','math',1,2,'u3','L04','g1_2_math_u3_L04_challenge','lesson_challenge','M1-2-u3-C3',3,'mc','auto','그림에서 네모 모양은 동그라미 모양보다 몇 개 더 많은가요?',ARRAY['M1-2-u3-X07','M1-2-u3-X06']::text[],false,'{"seq":3,"concept":"M1-2-u3-C3","difficulty":3,"kind":"mc","stem":"그림에서 네모 모양은 동그라미 모양보다 몇 개 더 많은가요?","asset":{"type":"shape_art","parts":[{"shape":"sq","n":5},{"shape":"tri","n":2},{"shape":"cir","n":3}],"name":"로봇"},"options":[{"t":"2개","correct":true},{"t":"3개","mis":"M1-2-u3-X07"},{"t":"5개","mis":"M1-2-u3-X06"}],"explanation":["네모는 5개, 동그라미는 3개예요.","5 − 3 = 2개 더 많아요.","더 많은 수에서 적은 수를 빼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L04_challenge#4','math',1,2,'u3','L04','g1_2_math_u3_L04_challenge','lesson_challenge','M1-2-u3-C3',3,'ox','auto','그림을 꾸밀 때 같은 모양을 여러 번 써도 돼요.',ARRAY['M1-2-u3-X07']::text[],false,'{"seq":4,"concept":"M1-2-u3-C3","difficulty":3,"kind":"ox","stem":"그림을 꾸밀 때 같은 모양을 여러 번 써도 돼요.","reason_options":[{"t":"모양은 몇 번이든 다시 쓸 수 있으니까","correct":true},{"t":"한 모양은 한 번만 쓸 수 있으니까","mis":"M1-2-u3-X07"}],"answer":"O","explanation":["꾸미기에서는 같은 모양을 여러 개 쓸 수 있어요.","그래서 네모가 여러 개 나올 수 있어요.","셀 때는 하나씩 표시하며 세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L04_challenge#5','math',1,2,'u3','L04','g1_2_math_u3_L04_challenge','lesson_challenge','M1-2-u3-C3',3,'error','auto','친구가 세모를 세면서 하나를 두 번 세었어요. 이때 생기는 일은 무엇인가요?',ARRAY['M1-2-u3-X07','M1-2-u3-X06']::text[],false,'{"seq":5,"concept":"M1-2-u3-C3","difficulty":3,"kind":"error","stem":"친구가 세모를 세면서 하나를 두 번 세었어요. 이때 생기는 일은 무엇인가요?","options":[{"t":"실제보다 수가 많아져요.","correct":true,"mis_target":"M1-2-u3-X07"},{"t":"실제보다 수가 적어져요.","mis":"M1-2-u3-X06"},{"t":"수가 달라지지 않아요.","mis":"M1-2-u3-X07"}],"explanation":["같은 것을 두 번 세면 하나가 더해져요.","그래서 실제보다 많아져요.","센 모양에 표시를 하면 막을 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L04_challenge#6','math',1,2,'u3','L04','g1_2_math_u3_L04_challenge','lesson_challenge','M1-2-u3-C3',3,'sa','auto','그림에서 가장 적게 쓴 모양은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"M1-2-u3-C3","difficulty":3,"kind":"sa","stem":"그림에서 가장 적게 쓴 모양은 몇 개인가요? 숫자로 쓰세요.","asset":{"type":"shape_art","parts":[{"shape":"sq","n":5},{"shape":"tri","n":2},{"shape":"cir","n":4}],"name":"기차"},"answer":["2"],"explanation":["네모 5개, 세모 2개, 동그라미 4개예요.","가장 적은 세모는 2개예요.","종류별로 센 다음 가장 작은 수를 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L04_challenge#7','math',1,2,'u3','L04','g1_2_math_u3_L04_challenge','lesson_challenge','M1-2-u3-C3',3,'mc','auto','네모 3개와 세모 2개로 꾸민 그림이 두 개 있어요. 두 그림에 쓴 모양은 모두 몇 개인가요?',ARRAY['M1-2-u3-X06','M1-2-u3-X07']::text[],false,'{"seq":7,"concept":"M1-2-u3-C3","difficulty":3,"kind":"mc","stem":"네모 3개와 세모 2개로 꾸민 그림이 두 개 있어요. 두 그림에 쓴 모양은 모두 몇 개인가요?","options":[{"t":"10개","correct":true},{"t":"5개","mis":"M1-2-u3-X06"},{"t":"6개","mis":"M1-2-u3-X07"}],"explanation":["그림 하나에 5개를 썼어요.","그림이 둘이니 5 + 5 = 10개예요.","그림 하나만 세면 답의 반이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L04_challenge#8','math',1,2,'u3','L04','g1_2_math_u3_L04_challenge','lesson_challenge','M1-2-u3-C3',4,'essay','teacher','네모 2개, 세모 1개, 동그라미 2개로 무엇을 꾸밀 수 있을까요? 만들 것을 쓰고 어느 모양을 어디에 쓸지 설명하세요.','{}'::text[],false,'{"seq":8,"concept":"M1-2-u3-C3","difficulty":4,"kind":"essay","stem":"네모 2개, 세모 1개, 동그라미 2개로 무엇을 꾸밀 수 있을까요? 만들 것을 쓰고 어느 모양을 어디에 쓸지 설명하세요.","answer_guide":"만들 것 이름 + 모양별 쓰임(예: 네모는 몸, 세모는 지붕, 동그라미는 바퀴)을 함께 쓰면 정답. 모양 수를 넘겨 쓰면 감점.","explanation":["주어진 모양 수를 먼저 확인해요.","네모 2개, 세모 1개, 동그라미 2개까지만 쓸 수 있어요.","각 모양을 어디에 쓸지 말로 설명해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L04_challenge#9','math',1,2,'u3','L04','g1_2_math_u3_L04_challenge','lesson_challenge','M1-2-u3-C3',4,'mc','auto','동그라미 4개를 쓴 그림은 무엇인가요?',ARRAY['M1-2-u3-X06']::text[],false,'{"seq":9,"concept":"M1-2-u3-C3","difficulty":4,"kind":"mc","stem":"동그라미 4개를 쓴 그림은 무엇인가요?","options":[{"t":"바퀴 2개, 눈 2개를 그린 자동차","correct":true},{"t":"지붕 하나만 그린 집","mis":"M1-2-u3-X06"},{"t":"창문 4개를 그린 건물","mis":"M1-2-u3-X06"}],"explanation":["바퀴 2개와 눈 2개는 모두 동그라미예요.","그래서 동그라미가 4개예요.","지붕은 세모, 창문은 네모라서 동그라미가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L04_challenge#10','math',1,2,'u3','L04','g1_2_math_u3_L04_challenge','lesson_challenge','M1-2-u3-C3',4,'sa','auto','그림에서 세모와 동그라미의 수가 같아요. 세모가 3개라면 동그라미는 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M1-2-u3-C3","difficulty":4,"kind":"sa","stem":"그림에서 세모와 동그라미의 수가 같아요. 세모가 3개라면 동그라미는 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["수가 같다고 했어요.","세모가 3개이니 동그라미도 3개예요.","‘같다’는 말은 수가 똑같다는 뜻이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L05_basic#1','math',1,2,'u3','L05','g1_2_math_u3_L05_basic','lesson_basic','M1-2-u3-C4',1,'mc','auto','시계를 보세요. 몇 시인가요?',ARRAY['M1-2-u3-X08','M1-2-u3-X09']::text[],true,'{"seq":1,"concept":"M1-2-u3-C4","difficulty":1,"kind":"mc","stem":"시계를 보세요. 몇 시인가요?","asset":{"type":"clock","h":3,"m":0},"options":[{"t":"3시","correct":true},{"t":"12시","mis":"M1-2-u3-X08"},{"t":"4시","mis":"M1-2-u3-X09"}],"explanation":["짧은바늘이 3을, 긴바늘이 12를 가리켜요.","그래서 3시예요.","긴바늘이 12를 가리키면 ‘몇 시’예요."],"variant_rule":{"time":{"hours":[1,12],"half":"oclock"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L05_basic#2','math',1,2,'u3','L05','g1_2_math_u3_L05_basic','lesson_basic','M1-2-u3-C4',1,'sa','auto','시계를 보세요. 몇 시인가요? ‘○시’로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M1-2-u3-C4","difficulty":1,"kind":"sa","stem":"시계를 보세요. 몇 시인가요? ‘○시’로 쓰세요.","asset":{"type":"clock","h":8,"m":0},"answer":["8시","8"],"explanation":["짧은바늘이 8을 가리켜요.","긴바늘은 12를 가리키니 8시예요.","짧은바늘부터 읽어요."],"variant_rule":{"time":{"hours":[1,12],"half":"oclock"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L05_basic#3','math',1,2,'u3','L05','g1_2_math_u3_L05_basic','lesson_basic','M1-2-u3-C4',1,'mc','auto','긴바늘이 12를 가리킬 때 시계는 어떻게 읽나요?',ARRAY['M1-2-u3-X10','M1-2-u3-X08']::text[],false,'{"seq":3,"concept":"M1-2-u3-C4","difficulty":1,"kind":"mc","stem":"긴바늘이 12를 가리킬 때 시계는 어떻게 읽나요?","options":[{"t":"‘몇 시’로 읽어요.","correct":true},{"t":"‘몇 시 30분’으로 읽어요.","mis":"M1-2-u3-X10"},{"t":"‘12시’로만 읽어요.","mis":"M1-2-u3-X08"}],"explanation":["긴바늘이 12에 있으면 정각이에요.","그래서 ‘몇 시’로 읽어요.","몇 시인지는 짧은바늘이 알려 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
