INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L05_basic#6','math',1,2,'u3','L05','g1_2_math_u3_L05_basic','lesson_basic','M1-2-u3-C4',2,'ox','auto','짧은바늘이 9, 긴바늘이 12를 가리키면 12시예요.',ARRAY['M1-2-u3-X08']::text[],false,'{"seq":6,"concept":"M1-2-u3-C4","difficulty":2,"kind":"ox","stem":"짧은바늘이 9, 긴바늘이 12를 가리키면 12시예요.","asset":{"type":"clock","h":9,"m":0},"reason_options":[{"t":"시는 짧은바늘이 알려 주니까","correct":true},{"t":"긴바늘이 가리키는 수를 읽으니까","mis":"M1-2-u3-X08"}],"answer":"X","explanation":["짧은바늘이 9를 가리키고 있어요.","그래서 12시가 아니라 9시예요.","긴바늘 12는 ‘정각’이라는 표시예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
