INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L05_challenge#3','math',1,2,'u3','L05','g1_2_math_u3_L05_challenge','lesson_challenge','M1-2-u3-C4',3,'mc','auto','5시를 나타낸 시계는 어떤 모습인가요?',ARRAY['M1-2-u3-X08','M1-2-u3-X10']::text[],false,'{"seq":3,"concept":"M1-2-u3-C4","difficulty":3,"kind":"mc","stem":"5시를 나타낸 시계는 어떤 모습인가요?","options":[{"t":"짧은바늘 5, 긴바늘 12","correct":true},{"t":"짧은바늘 12, 긴바늘 5","mis":"M1-2-u3-X08"},{"t":"짧은바늘 5, 긴바늘 6","mis":"M1-2-u3-X10"}],"explanation":["‘몇 시’는 긴바늘이 12에 있어요.","5시는 짧은바늘 5, 긴바늘 12예요.","두 바늘을 바꾸면 다른 시각이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L05_challenge#4','math',1,2,'u3','L05','g1_2_math_u3_L05_challenge','lesson_challenge','M1-2-u3-C4',3,'ox','auto','짧은바늘과 긴바늘의 길이가 바뀌어도 시각은 똑같이 읽어요.',ARRAY['M1-2-u3-X11']::text[],false,'{"seq":4,"concept":"M1-2-u3-C4","difficulty":3,"kind":"ox","stem":"짧은바늘과 긴바늘의 길이가 바뀌어도 시각은 똑같이 읽어요.","reason_options":[{"t":"바늘의 길이로 시와 분을 구별하니까","correct":true},{"t":"바늘은 길이와 상관없으니까","mis":"M1-2-u3-X11"}],"answer":"X","explanation":["짧은바늘은 시, 긴바늘은 분을 알려 줘요.","길이가 바뀌면 읽는 값도 달라져요.","시계를 그릴 때도 길이를 다르게 그려야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L05_challenge#5','math',1,2,'u3','L05','g1_2_math_u3_L05_challenge','lesson_challenge','M1-2-u3-C4',3,'error','auto','친구가 시계를 보고 ‘10시 30분’이라고 읽었어요. 잘못된 까닭은 무엇인가요?',ARRAY['M1-2-u3-X10','M1-2-u3-X08']::text[],false,'{"seq":5,"concept":"M1-2-u3-C4","difficulty":3,"kind":"error","stem":"친구가 시계를 보고 ‘10시 30분’이라고 읽었어요. 잘못된 까닭은 무엇인가요?","asset":{"type":"clock","h":10,"m":0},"options":[{"t":"긴바늘이 12를 가리키는데 30분이라고 했어요.","correct":true,"mis_target":"M1-2-u3-X10"},{"t":"짧은바늘이 10을 가리켜서 틀렸어요.","mis":"M1-2-u3-X08"},{"t":"시계에 30이라는 수가 없어서 틀렸어요.","mis":"M1-2-u3-X10"}],"explanation":["긴바늘이 12에 있으면 ‘정각’이에요.","그래서 10시 30분이 아니라 10시예요.","30분일 때는 긴바늘이 6을 가리켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L05_challenge#6','math',1,2,'u3','L05','g1_2_math_u3_L05_challenge','lesson_challenge','M1-2-u3-C4',3,'sa','auto','시계를 보세요. 몇 시인가요? ‘○시’로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M1-2-u3-C4","difficulty":3,"kind":"sa","stem":"시계를 보세요. 몇 시인가요? ‘○시’로 쓰세요.","asset":{"type":"clock","h":2,"m":0},"answer":["2시","2"],"explanation":["짧은바늘이 2를 가리켜요.","긴바늘이 12에 있으니 2시예요.","1과 3 사이의 수를 확인해요."],"variant_rule":{"time":{"hours":[1,12],"half":"oclock"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L05_challenge#7','math',1,2,'u3','L05','g1_2_math_u3_L05_challenge','lesson_challenge','M1-2-u3-C4',3,'mc','auto','아침에 일어나서 아침밥을 먹었어요. 아침밥을 먹은 시각으로 알맞은 것은 무엇인가요?',ARRAY['M1-2-u3-X09']::text[],false,'{"seq":7,"concept":"M1-2-u3-C4","difficulty":3,"kind":"mc","stem":"아침에 일어나서 아침밥을 먹었어요. 아침밥을 먹은 시각으로 알맞은 것은 무엇인가요?","options":[{"t":"7시","correct":true},{"t":"12시","mis":"M1-2-u3-X09"},{"t":"9시","mis":"M1-2-u3-X09"}],"explanation":["아침밥은 학교 가기 전에 먹어요.","7시가 가장 알맞아요.","12시는 점심, 9시는 수업 시간이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L05_challenge#8','math',1,2,'u3','L05','g1_2_math_u3_L05_challenge','lesson_challenge','M1-2-u3-C4',4,'essay','teacher','짧은바늘과 긴바늘이 하는 일이 어떻게 다른지 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M1-2-u3-C4","difficulty":4,"kind":"essay","stem":"짧은바늘과 긴바늘이 하는 일이 어떻게 다른지 쓰세요.","answer_guide":"‘짧은바늘은 시(몇 시), 긴바늘은 분을 알려 준다’는 뜻이 들어 있으면 정답. 한쪽만 쓰면 반만 맞음.","explanation":["두 바늘은 길이가 달라요.","짧은바늘은 시, 긴바늘은 분을 가리켜요.","역할을 바꿔 읽으면 시각이 틀려져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L05_challenge#9','math',1,2,'u3','L05','g1_2_math_u3_L05_challenge','lesson_challenge','M1-2-u3-C4',4,'mc','auto','다음 조건에 맞는 시각은 무엇인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L05_challenge#10','math',1,2,'u3','L05','g1_2_math_u3_L05_challenge','lesson_challenge','M1-2-u3-C4',4,'sa','auto','나는 긴바늘이 12를 가리키고, 짧은바늘은 11과 1 사이에 있어요. 나는 몇 시인가요? ‘○시’로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M1-2-u3-C4","difficulty":4,"kind":"sa","stem":"나는 긴바늘이 12를 가리키고, 짧은바늘은 11과 1 사이에 있어요. 나는 몇 시인가요? ‘○시’로 쓰세요.","answer":["12시","12"],"explanation":["긴바늘이 12이니 정각이에요.","11과 1 사이의 수는 12라서 12시예요.","시계에서 11 다음이 12, 그다음이 1이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
