INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L06_basic#3','math',1,2,'u3','L06','g1_2_math_u3_L06_basic','lesson_basic','M1-2-u3-C5',1,'mc','auto','긴바늘이 6을 가리킬 때는 몇 분인가요?',ARRAY['M1-2-u3-X10','M1-2-u3-X08']::text[],false,'{"seq":3,"concept":"M1-2-u3-C5","difficulty":1,"kind":"mc","stem":"긴바늘이 6을 가리킬 때는 몇 분인가요?","options":[{"t":"30분","correct":true},{"t":"6분","mis":"M1-2-u3-X10"},{"t":"12분","mis":"M1-2-u3-X08"}],"explanation":["긴바늘이 시계를 반 바퀴 돌면 6에 와요.","반 바퀴는 30분이에요.","6은 바늘이 가리키는 수일 뿐 분이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
