INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L06_basic#5','math',1,2,'u3','L06','g1_2_math_u3_L06_basic','lesson_basic','M1-2-u3-C5',2,'mc','auto','시계를 보세요. 몇 시 몇 분인가요?',ARRAY['M1-2-u3-X09','M1-2-u3-X10']::text[],true,'{"seq":5,"concept":"M1-2-u3-C5","difficulty":2,"kind":"mc","stem":"시계를 보세요. 몇 시 몇 분인가요?","asset":{"type":"clock","h":7,"m":30},"options":[{"t":"7시 30분","correct":true},{"t":"8시 30분","mis":"M1-2-u3-X09"},{"t":"7시 6분","mis":"M1-2-u3-X10"}],"explanation":["짧은바늘이 7과 8 사이에 있어요.","긴바늘이 6이니 7시 30분이에요.","가까운 수가 아니라 지나온 수를 읽어요."],"variant_rule":{"time":{"hours":[1,12],"half":"half"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L06_basic#6','math',1,2,'u3','L06','g1_2_math_u3_L06_basic','lesson_basic','M1-2-u3-C5',2,'ox','auto','짧은바늘이 3과 4 사이에 있고 긴바늘이 6을 가리키면 4시 30분이에요.',ARRAY['M1-2-u3-X09']::text[],false,'{"seq":6,"concept":"M1-2-u3-C5","difficulty":2,"kind":"ox","stem":"짧은바늘이 3과 4 사이에 있고 긴바늘이 6을 가리키면 4시 30분이에요.","asset":{"type":"clock","h":3,"m":30},"reason_options":[{"t":"짧은바늘이 지나온 수를 시로 읽으니까","correct":true},{"t":"짧은바늘이 더 가까운 수를 읽으니까","mis":"M1-2-u3-X09"}],"answer":"X","explanation":["짧은바늘이 3을 지나 4로 가는 중이에요.","그래서 3시 30분이에요.","아직 4에 닿지 않았으니 4시가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L06_basic#7','math',1,2,'u3','L06','g1_2_math_u3_L06_basic','lesson_basic','M1-2-u3-C5',2,'match','auto','시각과 알맞은 설명을 줄로 이어 보세요.','{}'::text[],false,'{"seq":7,"concept":"M1-2-u3-C5","difficulty":2,"kind":"match","stem":"시각과 알맞은 설명을 줄로 이어 보세요.","pairs":[{"l":"6시 30분","r":"짧은바늘이 6과 7 사이"},{"l":"1시 30분","r":"짧은바늘이 1과 2 사이"},{"l":"10시 30분","r":"짧은바늘이 10과 11 사이"}],"explanation":["30분일 때 짧은바늘은 두 수 사이에 있어요.","앞의 수가 ‘몇 시’예요.","긴바늘은 모두 6을 가리켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L06_basic#8','math',1,2,'u3','L06','g1_2_math_u3_L06_basic','lesson_basic','M1-2-u3-C5',2,'blank','auto','긴바늘이 6을 가리키면 (        )이라고 읽어요.',ARRAY['M1-2-u3-X10','M1-2-u3-X08']::text[],false,'{"seq":8,"concept":"M1-2-u3-C5","difficulty":2,"kind":"blank","stem":"긴바늘이 6을 가리키면 (        )이라고 읽어요.","options":[{"t":"30분","correct":true},{"t":"6분","mis":"M1-2-u3-X10"},{"t":"6시","mis":"M1-2-u3-X08"}],"explanation":["긴바늘이 반 바퀴 돌면 6에 와요.","그때가 30분이에요.","긴바늘은 시를 알려 주지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L06_basic#9','math',1,2,'u3','L06','g1_2_math_u3_L06_basic','lesson_basic','M1-2-u3-C5',2,'sa','auto','시계를 보세요. 몇 시 몇 분인가요? ‘○시 30분’으로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M1-2-u3-C5","difficulty":2,"kind":"sa","stem":"시계를 보세요. 몇 시 몇 분인가요? ‘○시 30분’으로 쓰세요.","asset":{"type":"clock","h":12,"m":30},"answer":["12시 30분","12시30분"],"explanation":["짧은바늘이 12와 1 사이에 있어요.","긴바늘이 6이니 12시 30분이에요.","12를 지났으니 12시로 읽어요."],"variant_rule":{"time":{"hours":[1,12],"half":"half"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L06_basic#10','math',1,2,'u3','L06','g1_2_math_u3_L06_basic','lesson_basic','M1-2-u3-C5',3,'error','auto','친구가 이 시계를 ‘8시 6분’이라고 읽었어요. 왜 틀렸을까요?',ARRAY['M1-2-u3-X10','M1-2-u3-X09']::text[],false,'{"seq":10,"concept":"M1-2-u3-C5","difficulty":3,"kind":"error","stem":"친구가 이 시계를 ‘8시 6분’이라고 읽었어요. 왜 틀렸을까요?","asset":{"type":"clock","h":8,"m":30},"options":[{"t":"긴바늘이 가리키는 6을 그대로 분으로 읽었어요.","correct":true,"mis_target":"M1-2-u3-X10"},{"t":"짧은바늘이 8과 9 사이에 있어서 틀렸어요.","mis":"M1-2-u3-X09"},{"t":"시계에 30이 없어서 읽을 수 없어요.","mis":"M1-2-u3-X10"}],"explanation":["긴바늘이 6을 가리키면 30분이에요.","6이라는 수를 그대로 분으로 읽어서 틀렸어요.","긴바늘은 한 칸이 5분씩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
