INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L06_challenge#2','math',1,2,'u3','L06','g1_2_math_u3_L06_challenge','lesson_challenge','M1-2-u3-C5',2,'sa','auto','시계를 보세요. 몇 시 몇 분인가요? ‘○시 30분’으로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M1-2-u3-C5","difficulty":2,"kind":"sa","stem":"시계를 보세요. 몇 시 몇 분인가요? ‘○시 30분’으로 쓰세요.","asset":{"type":"clock","h":4,"m":30},"answer":["4시 30분","4시30분"],"explanation":["짧은바늘이 4와 5 사이예요.","긴바늘이 6이니 4시 30분이에요.","지나온 수 4를 읽어요."],"variant_rule":{"time":{"hours":[1,12],"half":"half"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L06_challenge#3','math',1,2,'u3','L06','g1_2_math_u3_L06_challenge','lesson_challenge','M1-2-u3-C5',3,'mc','auto','3시 30분을 나타낸 시계는 어떤 모습인가요?',ARRAY['M1-2-u3-X10','M1-2-u3-X08']::text[],false,'{"seq":3,"concept":"M1-2-u3-C5","difficulty":3,"kind":"mc","stem":"3시 30분을 나타낸 시계는 어떤 모습인가요?","options":[{"t":"짧은바늘이 3과 4 사이, 긴바늘이 6","correct":true},{"t":"짧은바늘이 3, 긴바늘이 12","mis":"M1-2-u3-X10"},{"t":"짧은바늘이 6, 긴바늘이 3","mis":"M1-2-u3-X08"}],"explanation":["30분이면 긴바늘은 6에 있어요.","짧은바늘은 3을 지나 4로 가는 중이에요.","긴바늘 12는 정각을 뜻해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L06_challenge#4','math',1,2,'u3','L06','g1_2_math_u3_L06_challenge','lesson_challenge','M1-2-u3-C5',3,'ox','auto','몇 시 30분일 때 짧은바늘은 숫자 위에 딱 놓여 있어요.',ARRAY['M1-2-u3-X09']::text[],false,'{"seq":4,"concept":"M1-2-u3-C5","difficulty":3,"kind":"ox","stem":"몇 시 30분일 때 짧은바늘은 숫자 위에 딱 놓여 있어요.","reason_options":[{"t":"30분이면 짧은바늘이 두 수 사이에 있으니까","correct":true},{"t":"짧은바늘은 늘 숫자 위에 있으니까","mis":"M1-2-u3-X09"}],"answer":"X","explanation":["시간이 반쯤 지나면 짧은바늘도 반쯤 움직여요.","그래서 두 수 사이에 있어요.","숫자 위에 딱 놓이는 때는 정각이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L06_challenge#5','math',1,2,'u3','L06','g1_2_math_u3_L06_challenge','lesson_challenge','M1-2-u3-C5',3,'error','auto','친구가 이 시계를 ‘7시 30분’이라고 읽었어요. 왜 틀렸을까요?',ARRAY['M1-2-u3-X09','M1-2-u3-X10','M1-2-u3-X08']::text[],true,'{"seq":5,"concept":"M1-2-u3-C5","difficulty":3,"kind":"error","stem":"친구가 이 시계를 ‘7시 30분’이라고 읽었어요. 왜 틀렸을까요?","asset":{"type":"clock","h":6,"m":30},"options":[{"t":"짧은바늘이 6과 7 사이인데 뒤의 수를 읽었어요.","correct":true,"mis_target":"M1-2-u3-X09"},{"t":"긴바늘이 6이라 30분이 아니에요.","mis":"M1-2-u3-X10"},{"t":"짧은바늘과 긴바늘을 바꿔 읽었어요.","mis":"M1-2-u3-X08"}],"explanation":["짧은바늘이 6을 지나 7로 가는 중이에요.","지나온 수를 읽어야 하니 6시 30분이에요.","가까워 보인다고 다음 수를 읽으면 안 돼요."],"variant_rule":{"time":{"hours":[1,12],"half":"half"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L06_challenge#6','math',1,2,'u3','L06','g1_2_math_u3_L06_challenge','lesson_challenge','M1-2-u3-C5',3,'sa','auto','시계를 보세요. 몇 시 몇 분인가요? ‘○시 30분’으로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M1-2-u3-C5","difficulty":3,"kind":"sa","stem":"시계를 보세요. 몇 시 몇 분인가요? ‘○시 30분’으로 쓰세요.","asset":{"type":"clock","h":1,"m":30},"answer":["1시 30분","1시30분"],"explanation":["짧은바늘이 1과 2 사이예요.","긴바늘이 6이니 1시 30분이에요.","12를 지나 1로 온 것을 확인해요."],"variant_rule":{"time":{"hours":[1,12],"half":"half"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L06_challenge#7','math',1,2,'u3','L06','g1_2_math_u3_L06_challenge','lesson_challenge','M1-2-u3-C5',3,'mc','auto','긴바늘이 12에서 6까지 움직였어요. 얼마만큼 지났나요?',ARRAY['M1-2-u3-X10','M1-2-u3-X08']::text[],false,'{"seq":7,"concept":"M1-2-u3-C5","difficulty":3,"kind":"mc","stem":"긴바늘이 12에서 6까지 움직였어요. 얼마만큼 지났나요?","options":[{"t":"30분","correct":true},{"t":"6분","mis":"M1-2-u3-X10"},{"t":"1시간","mis":"M1-2-u3-X08"}],"explanation":["긴바늘이 12에서 6까지는 반 바퀴예요.","반 바퀴는 30분이에요.","한 바퀴를 다 돌면 1시간이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L06_challenge#8','math',1,2,'u3','L06','g1_2_math_u3_L06_challenge','lesson_challenge','M1-2-u3-C5',4,'essay','teacher','‘몇 시’와 ‘몇 시 30분’은 시계에서 무엇이 다른지 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M1-2-u3-C5","difficulty":4,"kind":"essay","stem":"‘몇 시’와 ‘몇 시 30분’은 시계에서 무엇이 다른지 쓰세요.","answer_guide":"‘긴바늘이 12면 몇 시, 6이면 몇 시 30분’ 또는 ‘30분일 때 짧은바늘이 두 수 사이에 있다’는 내용이 들어가면 정답.","explanation":["두 시각의 긴바늘 자리를 견줘 보세요.","짧은바늘의 자리도 다르게 보여요.","두 바늘을 모두 말하면 좋은 답이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L06_challenge#9','math',1,2,'u3','L06','g1_2_math_u3_L06_challenge','lesson_challenge','M1-2-u3-C5',4,'mc','auto','다음 조건에 맞는 시각은 무엇인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L06_challenge#10','math',1,2,'u3','L06','g1_2_math_u3_L06_challenge','lesson_challenge','M1-2-u3-C5',4,'sa','auto','나는 긴바늘이 6을 가리키고 짧은바늘은 10과 11 사이에 있어요. 나는 몇 시 몇 분인가요? ‘○시 30분’으로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M1-2-u3-C5","difficulty":4,"kind":"sa","stem":"나는 긴바늘이 6을 가리키고 짧은바늘은 10과 11 사이에 있어요. 나는 몇 시 몇 분인가요? ‘○시 30분’으로 쓰세요.","answer":["10시 30분","10시30분"],"explanation":["긴바늘 6은 30분이에요.","짧은바늘이 지나온 수는 10이에요.","그래서 10시 30분이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L07_basic#1','math',1,2,'u3','L07','g1_2_math_u3_L07_basic','lesson_basic','M1-2-u3-C6',1,'mc','auto','4시를 시계에 나타내려면 긴바늘을 어디에 그려야 하나요?',ARRAY['M1-2-u3-X10','M1-2-u3-X08']::text[],false,'{"seq":1,"concept":"M1-2-u3-C6","difficulty":1,"kind":"mc","stem":"4시를 시계에 나타내려면 긴바늘을 어디에 그려야 하나요?","asset":{"type":"clock","h":4,"m":0,"hands":"none"},"options":[{"t":"12","correct":true},{"t":"6","mis":"M1-2-u3-X10"},{"t":"4","mis":"M1-2-u3-X08"}],"explanation":["‘몇 시’는 긴바늘이 12에 있어요.","그래서 긴바늘을 12에 그려요.","짧은바늘을 4에 그리면 4시가 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L07_basic#2','math',1,2,'u3','L07','g1_2_math_u3_L07_basic','lesson_basic','M1-2-u3-C6',1,'sa','auto','6시 30분을 시계에 나타내려면 긴바늘을 어느 수에 그려야 하나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"M1-2-u3-C6","difficulty":1,"kind":"sa","stem":"6시 30분을 시계에 나타내려면 긴바늘을 어느 수에 그려야 하나요? 숫자로 쓰세요.","asset":{"type":"clock","h":6,"m":30,"hands":"none"},"answer":["6"],"explanation":["30분이면 긴바늘이 반 바퀴 돌아요.","반 바퀴는 6이에요.","짧은바늘은 6과 7 사이에 그려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L07_basic#3','math',1,2,'u3','L07','g1_2_math_u3_L07_basic','lesson_basic','M1-2-u3-C6',1,'mc','auto','시계를 그릴 때 짧은바늘은 어떻게 그려야 하나요?',ARRAY['M1-2-u3-X11']::text[],false,'{"seq":3,"concept":"M1-2-u3-C6","difficulty":1,"kind":"mc","stem":"시계를 그릴 때 짧은바늘은 어떻게 그려야 하나요?","options":[{"t":"긴바늘보다 짧게 그려요.","correct":true},{"t":"긴바늘보다 길게 그려요.","mis":"M1-2-u3-X11"},{"t":"길이는 아무래도 괜찮아요.","mis":"M1-2-u3-X11"}],"explanation":["시계에는 길이가 다른 두 바늘이 있어요.","시를 알려 주는 바늘이 더 짧아요.","길이를 바꿔 그리면 시각을 잘못 읽게 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L07_basic#4','math',1,2,'u3','L07','g1_2_math_u3_L07_basic','lesson_basic','M1-2-u3-C6',1,'sa','auto','시계를 보세요. 몇 시인가요? ‘○시’로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M1-2-u3-C6","difficulty":1,"kind":"sa","stem":"시계를 보세요. 몇 시인가요? ‘○시’로 쓰세요.","asset":{"type":"clock","h":10,"m":0},"answer":["10시","10"],"explanation":["짧은바늘이 10을 가리켜요.","긴바늘이 12에 있으니 10시예요.","먼저 짧은바늘부터 봐요."],"variant_rule":{"time":{"hours":[1,12],"half":"both"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L07_basic#5','math',1,2,'u3','L07','g1_2_math_u3_L07_basic','lesson_basic','M1-2-u3-C6',2,'mc','auto','다음 중 학교에서 점심을 먹는 시각으로 가장 알맞은 것은 무엇인가요?',ARRAY['M1-2-u3-X09']::text[],false,'{"seq":5,"concept":"M1-2-u3-C6","difficulty":2,"kind":"mc","stem":"다음 중 학교에서 점심을 먹는 시각으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"12시 30분","correct":true},{"t":"7시","mis":"M1-2-u3-X09"},{"t":"10시 30분","mis":"M1-2-u3-X09"}],"explanation":["점심은 낮에 먹어요.","12시 30분이 가장 알맞아요.","7시는 아침, 10시 30분은 수업 시간이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L07_basic#6','math',1,2,'u3','L07','g1_2_math_u3_L07_basic','lesson_basic','M1-2-u3-C6',2,'ox','auto','9시와 9시 30분 가운데 9시가 더 먼저예요.',ARRAY['M1-2-u3-X09']::text[],false,'{"seq":6,"concept":"M1-2-u3-C6","difficulty":2,"kind":"ox","stem":"9시와 9시 30분 가운데 9시가 더 먼저예요.","reason_options":[{"t":"9시가 지나야 30분이 되니까","correct":true},{"t":"30분이 붙으면 더 먼저니까","mis":"M1-2-u3-X09"}],"answer":"O","explanation":["시계는 앞에서 뒤로 흘러가요.","9시가 지난 다음 9시 30분이 돼요.","그래서 9시가 더 먼저예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L07_basic#7','math',1,2,'u3','L07','g1_2_math_u3_L07_basic','lesson_basic','M1-2-u3-C6',2,'match','auto','하는 일과 알맞은 시각을 줄로 이어 보세요.','{}'::text[],false,'{"seq":7,"concept":"M1-2-u3-C6","difficulty":2,"kind":"match","stem":"하는 일과 알맞은 시각을 줄로 이어 보세요.","pairs":[{"l":"아침에 일어나기","r":"7시"},{"l":"점심 먹기","r":"12시 30분"},{"l":"잠자리에 들기","r":"9시 30분"}],"explanation":["하루의 흐름을 떠올려 보세요.","아침 - 낮 - 저녁 순서로 이어져요.","시각의 앞뒤를 견주면 쉬워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L07_basic#8','math',1,2,'u3','L07','g1_2_math_u3_L07_basic','lesson_basic','M1-2-u3-C6',2,'blank','auto','2시 30분을 나타내려면 짧은바늘을 2와 (        ) 사이에 그려요.',ARRAY['M1-2-u3-X09','M1-2-u3-X10']::text[],false,'{"seq":8,"concept":"M1-2-u3-C6","difficulty":2,"kind":"blank","stem":"2시 30분을 나타내려면 짧은바늘을 2와 (        ) 사이에 그려요.","asset":{"type":"clock","h":2,"m":30,"hands":"none"},"options":[{"t":"3","correct":true},{"t":"1","mis":"M1-2-u3-X09"},{"t":"6","mis":"M1-2-u3-X10"}],"explanation":["30분은 두 수의 가운데쯤이에요.","2시 30분이니 2와 3 사이예요.","6은 긴바늘이 가는 자리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L07_basic#9','math',1,2,'u3','L07','g1_2_math_u3_L07_basic','lesson_basic','M1-2-u3-C6',2,'sa','auto','시계를 보세요. 몇 시 몇 분인가요? ‘○시 30분’으로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M1-2-u3-C6","difficulty":2,"kind":"sa","stem":"시계를 보세요. 몇 시 몇 분인가요? ‘○시 30분’으로 쓰세요.","asset":{"type":"clock","h":3,"m":30},"answer":["3시 30분","3시30분"],"explanation":["짧은바늘이 3과 4 사이예요.","긴바늘이 6이니 3시 30분이에요.","지나온 수를 시로 읽어요."],"variant_rule":{"time":{"hours":[1,12],"half":"both"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L07_basic#10','math',1,2,'u3','L07','g1_2_math_u3_L07_basic','lesson_basic','M1-2-u3-C6',3,'error','auto','친구가 5시를 시계에 나타냈어요. 잘못된 점은 무엇인가요?',ARRAY['M1-2-u3-X11','M1-2-u3-X08']::text[],false,'{"seq":10,"concept":"M1-2-u3-C6","difficulty":3,"kind":"error","stem":"친구가 5시를 시계에 나타냈어요. 잘못된 점은 무엇인가요?","options":[{"t":"긴바늘과 짧은바늘의 길이를 바꿔 그렸어요.","correct":true,"mis_target":"M1-2-u3-X11"},{"t":"긴바늘을 12에 그렸어요.","mis":"M1-2-u3-X08"},{"t":"짧은바늘을 5에 그렸어요.","mis":"M1-2-u3-X08"}],"explanation":["5시는 짧은바늘 5, 긴바늘 12가 맞아요.","두 바늘의 길이를 바꿔 그리면 시와 분이 뒤바뀌어요.","짧은바늘은 언제나 더 짧게 그려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L07_challenge#1','math',1,2,'u3','L07','g1_2_math_u3_L07_challenge','lesson_challenge','M1-2-u3-C6',2,'mc','auto','시계를 보세요. 몇 시 몇 분인가요?',ARRAY['M1-2-u3-X09','M1-2-u3-X10']::text[],true,'{"seq":1,"concept":"M1-2-u3-C6","difficulty":2,"kind":"mc","stem":"시계를 보세요. 몇 시 몇 분인가요?","asset":{"type":"clock","h":8,"m":30},"options":[{"t":"8시 30분","correct":true},{"t":"9시 30분","mis":"M1-2-u3-X09"},{"t":"8시 6분","mis":"M1-2-u3-X10"}],"explanation":["짧은바늘이 8과 9 사이예요.","긴바늘이 6이니 8시 30분이에요.","지나온 수 8을 읽어요."],"variant_rule":{"time":{"hours":[1,12],"half":"both"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L07_challenge#2','math',1,2,'u3','L07','g1_2_math_u3_L07_challenge','lesson_challenge','M1-2-u3-C6',2,'sa','auto','7시를 시계에 나타내려면 짧은바늘을 어느 수에 그려야 하나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"M1-2-u3-C6","difficulty":2,"kind":"sa","stem":"7시를 시계에 나타내려면 짧은바늘을 어느 수에 그려야 하나요? 숫자로 쓰세요.","asset":{"type":"clock","h":7,"m":0,"hands":"none"},"answer":["7"],"explanation":["‘몇 시’는 짧은바늘이 그 수를 가리켜요.","7시니까 짧은바늘을 7에 그려요.","긴바늘은 12에 그려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L07_challenge#3','math',1,2,'u3','L07','g1_2_math_u3_L07_challenge','lesson_challenge','M1-2-u3-C6',3,'mc','auto','다음 세 시각을 이른 것부터 놓은 것은 무엇인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L07_challenge#4','math',1,2,'u3','L07','g1_2_math_u3_L07_challenge','lesson_challenge','M1-2-u3-C6',3,'ox','auto','짧은바늘이 2와 3 사이에 있으면 아직 3시가 되지 않았어요.',ARRAY['M1-2-u3-X09']::text[],false,'{"seq":4,"concept":"M1-2-u3-C6","difficulty":3,"kind":"ox","stem":"짧은바늘이 2와 3 사이에 있으면 아직 3시가 되지 않았어요.","asset":{"type":"clock","h":2,"m":30},"reason_options":[{"t":"짧은바늘이 3에 닿아야 3시가 되니까","correct":true},{"t":"사이에 있으면 벌써 3시가 지났으니까","mis":"M1-2-u3-X09"}],"answer":"O","explanation":["짧은바늘은 2를 지나 3으로 가는 중이에요.","3에 닿기 전이니 아직 3시가 아니에요.","이때는 2시 몇 분으로 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L07_challenge#5','math',1,2,'u3','L07','g1_2_math_u3_L07_challenge','lesson_challenge','M1-2-u3-C6',3,'error','auto','친구가 ‘11시 30분’을 나타내려고 짧은바늘을 12에, 긴바늘을 6에 그렸어요. 잘못된 점은 무엇인가요?',ARRAY['M1-2-u3-X09','M1-2-u3-X10','M1-2-u3-X08']::text[],false,'{"seq":5,"concept":"M1-2-u3-C6","difficulty":3,"kind":"error","stem":"친구가 ‘11시 30분’을 나타내려고 짧은바늘을 12에, 긴바늘을 6에 그렸어요. 잘못된 점은 무엇인가요?","options":[{"t":"짧은바늘은 11과 12 사이에 그려야 해요.","correct":true,"mis_target":"M1-2-u3-X09"},{"t":"긴바늘은 12에 그려야 해요.","mis":"M1-2-u3-X10"},{"t":"두 바늘을 모두 6에 그려야 해요.","mis":"M1-2-u3-X08"}],"explanation":["11시 30분은 아직 12시가 되기 전이에요.","짧은바늘은 11과 12 사이에 있어야 해요.","긴바늘 6은 알맞게 그렸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L07_challenge#6','math',1,2,'u3','L07','g1_2_math_u3_L07_challenge','lesson_challenge','M1-2-u3-C6',3,'sa','auto','은서는 3시에 놀이터에 가서 3시 30분에 집에 왔어요. 놀이터에 있던 시간은 몇 분인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"M1-2-u3-C6","difficulty":3,"kind":"sa","stem":"은서는 3시에 놀이터에 가서 3시 30분에 집에 왔어요. 놀이터에 있던 시간은 몇 분인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["3시에서 3시 30분까지예요.","긴바늘이 12에서 6까지 반 바퀴 돌았어요.","반 바퀴는 30분이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L07_challenge#7','math',1,2,'u3','L07','g1_2_math_u3_L07_challenge','lesson_challenge','M1-2-u3-C6',3,'mc','auto','긴바늘이 12를 가리키고 짧은바늘이 6에 있어요. 30분이 지나면 시계는 어떻게 되나요?',ARRAY['M1-2-u3-X09','M1-2-u3-X10']::text[],false,'{"seq":7,"concept":"M1-2-u3-C6","difficulty":3,"kind":"mc","stem":"긴바늘이 12를 가리키고 짧은바늘이 6에 있어요. 30분이 지나면 시계는 어떻게 되나요?","options":[{"t":"짧은바늘이 6과 7 사이, 긴바늘이 6","correct":true},{"t":"짧은바늘이 7, 긴바늘이 12","mis":"M1-2-u3-X09"},{"t":"짧은바늘이 6, 긴바늘이 12 그대로","mis":"M1-2-u3-X10"}],"explanation":["30분이 지나면 긴바늘이 반 바퀴 돌아 6에 와요.","짧은바늘도 조금 움직여 6과 7 사이가 돼요.","6시 30분을 나타내는 모습이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L07_challenge#8','math',1,2,'u3','L07','g1_2_math_u3_L07_challenge','lesson_challenge','M1-2-u3-C6',4,'essay','teacher','내가 아침에 학교에 가는 시각을 쓰고, 그 시각을 시계에 어떻게 나타내면 되는지 설명하세요.','{}'::text[],false,'{"seq":8,"concept":"M1-2-u3-C6","difficulty":4,"kind":"essay","stem":"내가 아침에 학교에 가는 시각을 쓰고, 그 시각을 시계에 어떻게 나타내면 되는지 설명하세요.","answer_guide":"시각(○시 또는 ○시 30분) + 두 바늘의 자리(짧은바늘 어디, 긴바늘 12 또는 6)를 함께 쓰면 정답. 시각만 쓰면 반만 맞음.","explanation":["내가 집을 나서는 시각을 떠올려요.","‘몇 시’면 긴바늘이 12, ‘몇 시 30분’이면 6이에요.","짧은바늘 자리도 함께 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L07_challenge#9','math',1,2,'u3','L07','g1_2_math_u3_L07_challenge','lesson_challenge','M1-2-u3-C6',4,'mc','auto','다음 조건에 모두 맞는 시각은 무엇인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_L07_challenge#10','math',1,2,'u3','L07','g1_2_math_u3_L07_challenge','lesson_challenge','M1-2-u3-C6',4,'sa','auto','민호는 1시에 숙제를 시작해서 1시 30분에 끝냈어요. 끝낸 시각의 짧은바늘은 어느 두 수 사이에 있나요? 두 수를 차례로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M1-2-u3-C6","difficulty":4,"kind":"sa","stem":"민호는 1시에 숙제를 시작해서 1시 30분에 끝냈어요. 끝낸 시각의 짧은바늘은 어느 두 수 사이에 있나요? 두 수를 차례로 쓰세요.","answer":["1과 2","1, 2","1 2"],"explanation":["1시 30분은 1시를 지난 시각이에요.","짧은바늘은 1을 지나 2로 가는 중이에요.","그래서 1과 2 사이에 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_a#1','math',1,2,'u3','review','g1_2_math_u3_review_a','unit_review','M1-2-u3-C1',1,'mc','auto','그림을 보세요. 세모 모양은 몇 개인가요?',ARRAY['M1-2-u3-X07','M1-2-u3-X06']::text[],true,'{"concept":"M1-2-u3-C1","difficulty":1,"kind":"mc","stem":"그림을 보세요. 세모 모양은 몇 개인가요?","asset":{"type":"shape_row","shapes":["tri","cir","sq","tri","cir"]},"options":[{"t":"2","correct":true},{"t":"3","mis":"M1-2-u3-X07"},{"t":"1","mis":"M1-2-u3-X06"}],"explanation":["세모 모양만 골라 손으로 짚어 보세요.","세모는 2개예요.","센 것에 표시를 하면 두 번 세지 않아요."],"variant_rule":{"shapes":{"len":[4,6],"ask":"count","target":"tri"}},"seq":1}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_a#2','math',1,2,'u3','review','g1_2_math_u3_review_a','unit_review','M1-2-u3-C1',1,'sa','auto','그림을 보세요. 동그라미 모양은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"concept":"M1-2-u3-C1","difficulty":1,"kind":"sa","stem":"그림을 보세요. 동그라미 모양은 몇 개인가요? 숫자로 쓰세요.","asset":{"type":"shape_row","shapes":["cir","sq","cir","tri","cir"]},"answer":["3"],"explanation":["동그라미만 골라 세어요.","동그라미는 3개예요.","네모와 세모는 세지 않아요."],"variant_rule":{"shapes":{"len":[4,6],"ask":"count","target":"cir"}},"seq":2}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_a#3','math',1,2,'u3','review','g1_2_math_u3_review_a','unit_review','M1-2-u3-C1',2,'blank','auto','동전과 접시는 모두 (        ) 모양이에요.',ARRAY['M1-2-u3-X02']::text[],false,'{"concept":"M1-2-u3-C1","difficulty":2,"kind":"blank","stem":"동전과 접시는 모두 (        ) 모양이에요.","options":[{"t":"동그라미","correct":true},{"t":"네모","mis":"M1-2-u3-X02"},{"t":"세모","mis":"M1-2-u3-X02"}],"explanation":["동전과 접시의 테두리를 따라가 보세요.","둘 다 굽은 선으로 둥글게 이어져 동그라미 모양이에요.","크기가 달라도 모양 이름은 같아요."],"seq":3}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_a#4','math',1,2,'u3','review','g1_2_math_u3_review_a','unit_review','M1-2-u3-C1',2,'match','auto','물건과 알맞은 모양을 줄로 이어 보세요.','{}'::text[],false,'{"concept":"M1-2-u3-C1","difficulty":2,"kind":"match","stem":"물건과 알맞은 모양을 줄로 이어 보세요.","pairs":[{"l":"📺 텔레비전","r":"네모 모양"},{"l":"🍕 피자 조각","r":"세모 모양"},{"l":"⏰ 시계","r":"동그라미 모양"}],"explanation":["물건의 테두리 생김새를 봐요.","텔레비전은 네모, 피자 조각은 세모, 시계는 동그라미예요.","색깔이나 크기는 모양과 상관이 없어요."],"seq":4}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_a#5','math',1,2,'u3','review','g1_2_math_u3_review_a','unit_review','M1-2-u3-C1',3,'error','auto','세 친구가 네모 모양 물건을 하나씩 골랐어요. 잘못 고른 친구는 누구인가요?',ARRAY['M1-2-u3-X02','M1-2-u3-X01']::text[],false,'{"concept":"M1-2-u3-C1","difficulty":3,"kind":"error","stem":"세 친구가 네모 모양 물건을 하나씩 골랐어요. 잘못 고른 친구는 누구인가요?","options":[{"t":"공을 고른 예나","correct":true,"mis_target":"M1-2-u3-X02"},{"t":"공책을 고른 준수","mis":"M1-2-u3-X02"},{"t":"창문을 고른 서아","mis":"M1-2-u3-X01"}],"explanation":["공책과 창문은 곧은 선 네 개로 둘러싸여 있어요.","공은 굽은 선으로 둥글게 이어진 동그라미 모양이에요.","네모인지 볼 때는 뾰족한 곳이 네 군데인지 확인해요."],"seq":5}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_a#6','math',1,2,'u3','review','g1_2_math_u3_review_a','unit_review','M1-2-u3-C2',1,'sa','auto','네모 모양은 곧은 선이 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"concept":"M1-2-u3-C2","difficulty":1,"kind":"sa","stem":"네모 모양은 곧은 선이 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["네모의 테두리를 따라가며 선을 세어요.","곧은 선이 4개예요.","뾰족한 곳도 4군데예요."],"seq":6}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_a#7','math',1,2,'u3','review','g1_2_math_u3_review_a','unit_review','M1-2-u3-C2',1,'mc','auto','점선으로 표시한 둘째 그림은 뾰족한 곳이 몇 군데인가요?',ARRAY['M1-2-u3-X04','M1-2-u3-X05']::text[],false,'{"concept":"M1-2-u3-C2","difficulty":1,"kind":"mc","stem":"점선으로 표시한 둘째 그림은 뾰족한 곳이 몇 군데인가요?","asset":{"type":"shape_row","shapes":["cir","sq","tri","cir"],"mark":2},"options":[{"t":"4군데","correct":true},{"t":"3군데","mis":"M1-2-u3-X04"},{"t":"없어요","mis":"M1-2-u3-X05"}],"explanation":["표시한 것은 네모 모양이에요.","네모의 뾰족한 곳은 네 군데예요.","모양을 먼저 알아낸 다음 세어야 해요."],"seq":7}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_a#8','math',1,2,'u3','review','g1_2_math_u3_review_a','unit_review','M1-2-u3-C2',2,'ox','auto','동그라미 모양에는 뾰족한 곳이 있어요.',ARRAY['M1-2-u3-X05']::text[],false,'{"concept":"M1-2-u3-C2","difficulty":2,"kind":"ox","stem":"동그라미 모양에는 뾰족한 곳이 있어요.","reason_options":[{"t":"동그라미는 굽은 선으로만 이어져 있으니까","correct":true},{"t":"동그라미도 네 군데가 뾰족하니까","mis":"M1-2-u3-X05"}],"answer":"X","explanation":["동그라미를 손가락으로 따라가 보세요.","끝까지 부드럽게 이어져서 뾰족한 곳이 없어요.","뾰족한 곳은 곧은 선이 만나는 자리에 생겨요."],"seq":8}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_a#9','math',1,2,'u3','review','g1_2_math_u3_review_a','unit_review','M1-2-u3-C2',3,'sa','auto','그림에서 곧은 선으로 둘러싸인 모양은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"concept":"M1-2-u3-C2","difficulty":3,"kind":"sa","stem":"그림에서 곧은 선으로 둘러싸인 모양은 모두 몇 개인가요? 숫자로 쓰세요.","asset":{"type":"shape_row","shapes":["sq","cir","tri","sq","tri","cir"]},"answer":["4"],"explanation":["곧은 선으로 둘러싸인 모양은 네모와 세모예요.","네모 2개와 세모 2개를 더하면 4개예요.","동그라미는 세지 않아요."],"seq":9}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_a#10','math',1,2,'u3','review','g1_2_math_u3_review_a','unit_review','M1-2-u3-C3',1,'mc','auto','로봇 그림에 쓴 네모 모양은 몇 개인가요?',ARRAY['M1-2-u3-X06','M1-2-u3-X07']::text[],true,'{"concept":"M1-2-u3-C3","difficulty":1,"kind":"mc","stem":"로봇 그림에 쓴 네모 모양은 몇 개인가요?","asset":{"type":"shape_art","parts":[{"shape":"sq","n":4},{"shape":"tri","n":2},{"shape":"cir","n":3}],"name":"로봇"},"options":[{"t":"4","correct":true},{"t":"3","mis":"M1-2-u3-X06"},{"t":"5","mis":"M1-2-u3-X07"}],"explanation":["네모만 골라 하나씩 짚어요.","네모는 4개예요.","센 것에 표시하면 두 번 세지 않아요."],"variant_rule":{"art":{"n":[2,5],"ask":"sq"}},"seq":10}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_a#11','math',1,2,'u3','review','g1_2_math_u3_review_a','unit_review','M1-2-u3-C3',2,'sa','auto','배 그림에 쓴 모양은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"concept":"M1-2-u3-C3","difficulty":2,"kind":"sa","stem":"배 그림에 쓴 모양은 모두 몇 개인가요? 숫자로 쓰세요.","asset":{"type":"shape_art","parts":[{"shape":"sq","n":3},{"shape":"tri","n":4},{"shape":"cir","n":2}],"name":"배"},"answer":["9"],"explanation":["네모 3개, 세모 4개, 동그라미 2개예요.","3 + 4 + 2 = 9개예요.","종류별로 센 다음 모두 더해요."],"variant_rule":{"art":{"n":[1,5],"ask":"total"}},"seq":11}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_a#12','math',1,2,'u3','review','g1_2_math_u3_review_a','unit_review','M1-2-u3-C3',3,'mc','auto','기차 그림에서 가장 많이 쓴 모양은 무엇인가요?',ARRAY['M1-2-u3-X06']::text[],false,'{"concept":"M1-2-u3-C3","difficulty":3,"kind":"mc","stem":"기차 그림에서 가장 많이 쓴 모양은 무엇인가요?","asset":{"type":"shape_art","parts":[{"shape":"sq","n":5},{"shape":"tri","n":2},{"shape":"cir","n":3}],"name":"기차"},"options":[{"t":"네모 모양","correct":true},{"t":"세모 모양","mis":"M1-2-u3-X06"},{"t":"동그라미 모양","mis":"M1-2-u3-X06"}],"explanation":["네모 5개, 세모 2개, 동그라미 3개예요.","가장 많은 것은 네모 모양이에요.","종류별로 센 다음 수를 견줘요."],"seq":12}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_a#13','math',1,2,'u3','review','g1_2_math_u3_review_a','unit_review','M1-2-u3-C3',4,'error','auto','친구가 성 그림의 네모를 세어 보고 5개라고 했어요. 왜 틀렸을까요?',ARRAY['M1-2-u3-X06','M1-2-u3-X07','M1-2-u3-X01']::text[],false,'{"concept":"M1-2-u3-C3","difficulty":4,"kind":"error","stem":"친구가 성 그림의 네모를 세어 보고 5개라고 했어요. 왜 틀렸을까요?","asset":{"type":"shape_art","parts":[{"shape":"sq","n":6},{"shape":"tri","n":2},{"shape":"cir","n":2}],"name":"성"},"options":[{"t":"겹쳐 놓인 네모 하나를 빠뜨리고 세었어요.","correct":true,"mis_target":"M1-2-u3-X06"},{"t":"같은 네모를 두 번 세었어요.","mis":"M1-2-u3-X07"},{"t":"색깔이 다른 네모는 세면 안 되니까요.","mis":"M1-2-u3-X01"}],"explanation":["그림에는 네모가 6개 있어요.","겹친 곳에 숨은 네모를 빠뜨려서 5개가 되었어요.","센 모양에 표시를 하면 빠뜨리지 않아요."],"seq":13}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_a#14','math',1,2,'u3','review','g1_2_math_u3_review_a','unit_review','M1-2-u3-C4',1,'mc','auto','시계를 보세요. 몇 시인가요?',ARRAY['M1-2-u3-X08','M1-2-u3-X09']::text[],true,'{"concept":"M1-2-u3-C4","difficulty":1,"kind":"mc","stem":"시계를 보세요. 몇 시인가요?","asset":{"type":"clock","h":3,"m":0},"options":[{"t":"3시","correct":true},{"t":"12시","mis":"M1-2-u3-X08"},{"t":"4시","mis":"M1-2-u3-X09"}],"explanation":["짧은바늘이 3을 가리키고, 긴바늘이 12를 가리켜요.","그래서 3시예요.","긴바늘이 12를 가리키면 「몇 시」예요."],"variant_rule":{"time":{"hours":[1,12],"half":"oclock"}},"seq":14}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_a#15','math',1,2,'u3','review','g1_2_math_u3_review_a','unit_review','M1-2-u3-C4',1,'sa','auto','시계를 보세요. 몇 시인가요? ‘○시’로 쓰세요.','{}'::text[],true,'{"concept":"M1-2-u3-C4","difficulty":1,"kind":"sa","stem":"시계를 보세요. 몇 시인가요? ‘○시’로 쓰세요.","asset":{"type":"clock","h":8,"m":0},"answer":["8시","8"],"explanation":["짧은바늘이 8을 가리켜요.","긴바늘은 12를 가리키니 8시예요.","짧은바늘부터 읽어요."],"variant_rule":{"time":{"hours":[1,12],"half":"oclock"}},"seq":15}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_a#16','math',1,2,'u3','review','g1_2_math_u3_review_a','unit_review','M1-2-u3-C4',2,'blank','auto','은우는 (        )에 학교에 갔어요. 시계를 보고 답하세요.',ARRAY['M1-2-u3-X08','M1-2-u3-X09']::text[],true,'{"concept":"M1-2-u3-C4","difficulty":2,"kind":"blank","stem":"은우는 (        )에 학교에 갔어요. 시계를 보고 답하세요.","asset":{"type":"clock","h":9,"m":0},"options":[{"t":"9시","correct":true},{"t":"12시","mis":"M1-2-u3-X08"},{"t":"10시","mis":"M1-2-u3-X09"}],"explanation":["짧은바늘이 9를 가리켜요.","긴바늘이 12에 있으니 9시예요.","짧은바늘이 지나온 수를 읽어요."],"variant_rule":{"time":{"hours":[1,12],"half":"oclock"}},"seq":16}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_a#17','math',1,2,'u3','review','g1_2_math_u3_review_a','unit_review','M1-2-u3-C4',3,'error','auto','친구가 이 시계를 보고 12시라고 읽었어요. 왜 틀렸을까요?',ARRAY['M1-2-u3-X08','M1-2-u3-X10']::text[],false,'{"concept":"M1-2-u3-C4","difficulty":3,"kind":"error","stem":"친구가 이 시계를 보고 12시라고 읽었어요. 왜 틀렸을까요?","asset":{"type":"clock","h":4,"m":0},"options":[{"t":"긴바늘이 가리키는 수를 시로 읽었어요.","correct":true,"mis_target":"M1-2-u3-X08"},{"t":"짧은바늘이 없어서 읽을 수 없어요.","mis":"M1-2-u3-X08"},{"t":"긴바늘이 6을 가리켜서 30분이에요.","mis":"M1-2-u3-X10"}],"explanation":["짧은바늘은 4를 가리키고 있어요.","긴바늘 12를 시로 읽어서 12시가 되었어요.","시는 언제나 짧은바늘이 알려 줘요."],"seq":17}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_a#18','math',1,2,'u3','review','g1_2_math_u3_review_a','unit_review','M1-2-u3-C5',1,'mc','auto','시계를 보세요. 몇 시 몇 분인가요?',ARRAY['M1-2-u3-X09','M1-2-u3-X10']::text[],true,'{"concept":"M1-2-u3-C5","difficulty":1,"kind":"mc","stem":"시계를 보세요. 몇 시 몇 분인가요?","asset":{"type":"clock","h":2,"m":30},"options":[{"t":"2시 30분","correct":true},{"t":"3시 30분","mis":"M1-2-u3-X09"},{"t":"2시 6분","mis":"M1-2-u3-X10"}],"explanation":["짧은바늘은 2와 3 사이, 긴바늘은 6을 가리켜요.","그래서 2시 30분이에요.","긴바늘이 6이면 30분이에요."],"variant_rule":{"time":{"hours":[1,12],"half":"half"}},"seq":18}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_a#19','math',1,2,'u3','review','g1_2_math_u3_review_a','unit_review','M1-2-u3-C5',2,'sa','auto','시계를 보세요. 몇 시 몇 분인가요? ‘○시 30분’으로 쓰세요.','{}'::text[],true,'{"concept":"M1-2-u3-C5","difficulty":2,"kind":"sa","stem":"시계를 보세요. 몇 시 몇 분인가요? ‘○시 30분’으로 쓰세요.","asset":{"type":"clock","h":5,"m":30},"answer":["5시 30분","5시30분"],"explanation":["짧은바늘이 5를 지나 6로 가는 중이에요.","긴바늘이 6이니 5시 30분이에요.","짧은바늘이 지나온 수를 읽어요."],"variant_rule":{"time":{"hours":[1,12],"half":"half"}},"seq":19}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_a#20','math',1,2,'u3','review','g1_2_math_u3_review_a','unit_review','M1-2-u3-C5',2,'ox','auto','이 시계는 3시 30분이에요.',ARRAY['M1-2-u3-X09']::text[],false,'{"concept":"M1-2-u3-C5","difficulty":2,"kind":"ox","stem":"이 시계는 3시 30분이에요.","asset":{"type":"clock","h":3,"m":30},"reason_options":[{"t":"짧은바늘이 지나온 수 3을 시로 읽으니까","correct":true},{"t":"짧은바늘이 4에 더 가까우니 4시 30분이니까","mis":"M1-2-u3-X09"}],"answer":"O","explanation":["짧은바늘은 3과 4 사이에 있어요.","긴바늘은 6이니 3시 30분 맞아요.","짧은바늘은 지나온 수, 긴바늘 6은 30분이에요."],"seq":20}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_a#21','math',1,2,'u3','review','g1_2_math_u3_review_a','unit_review','M1-2-u3-C5',3,'error','auto','친구가 이 시계를 ‘7시 30분’이라고 읽었어요. 왜 틀렸을까요?',ARRAY['M1-2-u3-X09','M1-2-u3-X10','M1-2-u3-X08']::text[],true,'{"concept":"M1-2-u3-C5","difficulty":3,"kind":"error","stem":"친구가 이 시계를 ‘7시 30분’이라고 읽었어요. 왜 틀렸을까요?","asset":{"type":"clock","h":6,"m":30},"options":[{"t":"짧은바늘이 6과 7 사이인데 뒤의 수를 읽었어요.","correct":true,"mis_target":"M1-2-u3-X09"},{"t":"긴바늘이 6이라 30분이 아니에요.","mis":"M1-2-u3-X10"},{"t":"짧은바늘과 긴바늘을 바꿔 읽었어요.","mis":"M1-2-u3-X08"}],"explanation":["짧은바늘이 6을 지나 7로 가는 중이에요.","지나온 수를 읽어야 하니 6시 30분이에요.","가까워 보인다고 다음 수를 읽으면 안 돼요."],"variant_rule":{"time":{"hours":[1,12],"half":"half"}},"seq":21}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_a#22','math',1,2,'u3','review','g1_2_math_u3_review_a','unit_review','M1-2-u3-C6',2,'mc','auto','4시를 시계에 나타내려면 긴바늘을 어디에 그려야 하나요?',ARRAY['M1-2-u3-X10','M1-2-u3-X08']::text[],false,'{"concept":"M1-2-u3-C6","difficulty":2,"kind":"mc","stem":"4시를 시계에 나타내려면 긴바늘을 어디에 그려야 하나요?","asset":{"type":"clock","h":4,"m":0,"hands":"none"},"options":[{"t":"12","correct":true},{"t":"6","mis":"M1-2-u3-X10"},{"t":"4","mis":"M1-2-u3-X08"}],"explanation":["「몇 시」는 긴바늘이 12에 있어요.","그래서 긴바늘을 12에 그려요.","짧은바늘을 4에 그리면 4시가 돼요."],"seq":22}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_a#23','math',1,2,'u3','review','g1_2_math_u3_review_a','unit_review','M1-2-u3-C6',3,'blank','auto','2시 30분을 나타내려면 짧은바늘을 2와 (        ) 사이에 그려요.',ARRAY['M1-2-u3-X09','M1-2-u3-X10']::text[],false,'{"concept":"M1-2-u3-C6","difficulty":3,"kind":"blank","stem":"2시 30분을 나타내려면 짧은바늘을 2와 (        ) 사이에 그려요.","asset":{"type":"clock","h":2,"m":30,"hands":"none"},"options":[{"t":"3","correct":true},{"t":"1","mis":"M1-2-u3-X09"},{"t":"6","mis":"M1-2-u3-X10"}],"explanation":["30분은 두 수의 가운데쯤이에요.","2시 30분이니 2와 3 사이예요.","6은 긴바늘이 가는 자리예요."],"seq":23}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_a#24','math',1,2,'u3','review','g1_2_math_u3_review_a','unit_review','M1-2-u3-C6',4,'mc','auto','하린는 3시 30분에 피아노 연습을 시작했어요. 이때 시계의 두 바늘은 어떻게 놓여 있나요?',ARRAY['M1-2-u3-X10','M1-2-u3-X09']::text[],false,'{"concept":"M1-2-u3-C6","difficulty":4,"kind":"mc","stem":"하린는 3시 30분에 피아노 연습을 시작했어요. 이때 시계의 두 바늘은 어떻게 놓여 있나요?","options":[{"t":"짧은바늘은 3과 4 사이, 긴바늘은 6","correct":true},{"t":"짧은바늘은 3, 긴바늘은 12","mis":"M1-2-u3-X10"},{"t":"짧은바늘은 4와 5 사이, 긴바늘은 6","mis":"M1-2-u3-X09"}],"explanation":["30분이면 긴바늘은 6에 있어요.","짧은바늘은 3을 지나 4로 가는 중이니 3과 4 사이예요.","긴바늘이 12에 있으면 3시가 돼 버려요."],"seq":24}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_a#25','math',1,2,'u3','review','g1_2_math_u3_review_a','unit_review','M1-2-u3-C6',4,'essay','teacher','잠자리에 드는 시각이 8시 30분이에요. 이 시각을 시계에 그린다면 짧은바늘과 긴바늘을 각각 어디에 그려야 하는지 쓰고, 그 까닭도 쓰세요.','{}'::text[],false,'{"concept":"M1-2-u3-C6","difficulty":4,"kind":"essay","stem":"잠자리에 드는 시각이 8시 30분이에요. 이 시각을 시계에 그린다면 짧은바늘과 긴바늘을 각각 어디에 그려야 하는지 쓰고, 그 까닭도 쓰세요.","asset":{"type":"clock","h":8,"m":30,"hands":"none"},"answer_guide":"짧은바늘 「8과 9 사이」 + 긴바늘 「6」 + 까닭(긴바늘이 6이면 30분 / 짧은바늘은 지나온 수를 읽는다)이 함께 있으면 정답. 두 바늘 자리만 맞고 까닭이 없으면 반만 맞음. 두 바늘 길이를 바꿔 쓰면 틀림.","explanation":["긴바늘은 6에 그려요 — 30분이니까요.","짧은바늘은 8과 9 사이에 그려요.","짧은바늘을 먼저 그리고 긴바늘을 길게 덧그려요."],"seq":25}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_b#1','math',1,2,'u3','review','g1_2_math_u3_review_b','unit_review','M1-2-u3-C1',1,'mc','auto','그림을 보세요. 네모 모양은 몇 개인가요?',ARRAY['M1-2-u3-X07','M1-2-u3-X06']::text[],true,'{"concept":"M1-2-u3-C1","difficulty":1,"kind":"mc","stem":"그림을 보세요. 네모 모양은 몇 개인가요?","asset":{"type":"shape_row","shapes":["sq","tri","sq","cir","sq"]},"options":[{"t":"3","correct":true},{"t":"4","mis":"M1-2-u3-X07"},{"t":"2","mis":"M1-2-u3-X06"}],"explanation":["네모 모양만 골라 손으로 짚어 보세요.","네모는 3개예요.","센 것에 표시를 하면 두 번 세지 않아요."],"variant_rule":{"shapes":{"len":[4,6],"ask":"count","target":"sq"}},"seq":1}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_b#2','math',1,2,'u3','review','g1_2_math_u3_review_b','unit_review','M1-2-u3-C1',1,'sa','auto','그림을 보세요. 세모 모양은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"concept":"M1-2-u3-C1","difficulty":1,"kind":"sa","stem":"그림을 보세요. 세모 모양은 몇 개인가요? 숫자로 쓰세요.","asset":{"type":"shape_row","shapes":["tri","cir","tri","sq"]},"answer":["2"],"explanation":["세모만 골라 세어요.","세모는 2개예요.","네모와 동그라미는 세지 않아요."],"variant_rule":{"shapes":{"len":[4,6],"ask":"count","target":"tri"}},"seq":2}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_b#3','math',1,2,'u3','review','g1_2_math_u3_review_b','unit_review','M1-2-u3-C1',2,'blank','auto','공책과 창문은 모두 (        ) 모양이에요.',ARRAY['M1-2-u3-X02']::text[],false,'{"concept":"M1-2-u3-C1","difficulty":2,"kind":"blank","stem":"공책과 창문은 모두 (        ) 모양이에요.","options":[{"t":"네모","correct":true},{"t":"세모","mis":"M1-2-u3-X02"},{"t":"동그라미","mis":"M1-2-u3-X02"}],"explanation":["공책과 창문의 테두리를 따라가 보세요.","둘 다 곧은 선 네 개로 이어져 네모 모양이에요.","크기가 달라도 모양 이름은 같아요."],"seq":3}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_b#4','math',1,2,'u3','review','g1_2_math_u3_review_b','unit_review','M1-2-u3-C1',2,'match','auto','물건과 알맞은 모양을 줄로 이어 보세요.','{}'::text[],false,'{"concept":"M1-2-u3-C1","difficulty":2,"kind":"match","stem":"물건과 알맞은 모양을 줄로 이어 보세요.","pairs":[{"l":"📖 책","r":"네모 모양"},{"l":"🍙 삼각김밥","r":"세모 모양"},{"l":"🪙 동전","r":"동그라미 모양"}],"explanation":["물건의 테두리 생김새를 봐요.","책은 네모, 삼각김밥은 세모, 동전은 동그라미예요.","색깔이나 크기는 모양과 상관이 없어요."],"seq":4}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_b#5','math',1,2,'u3','review','g1_2_math_u3_review_b','unit_review','M1-2-u3-C1',3,'error','auto','세 친구가 동그라미 모양 물건을 하나씩 골랐어요. 잘못 고른 친구는 누구인가요?',ARRAY['M1-2-u3-X02','M1-2-u3-X01']::text[],false,'{"concept":"M1-2-u3-C1","difficulty":3,"kind":"error","stem":"세 친구가 동그라미 모양 물건을 하나씩 골랐어요. 잘못 고른 친구는 누구인가요?","options":[{"t":"상자를 고른 민호","correct":true,"mis_target":"M1-2-u3-X02"},{"t":"동전을 고른 하은","mis":"M1-2-u3-X02"},{"t":"접시를 고른 지우","mis":"M1-2-u3-X01"}],"explanation":["동전과 접시는 굽은 선으로 둥글게 둘러싸여 있어요.","상자는 곧은 선 네 개로 이어진 네모 모양이에요.","동그라미인지 볼 때는 뾰족한 곳이 없는지 확인해요."],"seq":5}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_b#6','math',1,2,'u3','review','g1_2_math_u3_review_b','unit_review','M1-2-u3-C2',1,'sa','auto','세모 모양은 뾰족한 곳이 몇 군데인가요? 숫자로 쓰세요.','{}'::text[],false,'{"concept":"M1-2-u3-C2","difficulty":1,"kind":"sa","stem":"세모 모양은 뾰족한 곳이 몇 군데인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["세모의 꼭짓점을 하나씩 짚어요.","뾰족한 곳이 3군데예요.","곧은 선도 3개예요."],"seq":6}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_b#7','math',1,2,'u3','review','g1_2_math_u3_review_b','unit_review','M1-2-u3-C2',1,'mc','auto','점선으로 표시한 둘째 그림은 뾰족한 곳이 몇 군데인가요?',ARRAY['M1-2-u3-X04','M1-2-u3-X05']::text[],false,'{"concept":"M1-2-u3-C2","difficulty":1,"kind":"mc","stem":"점선으로 표시한 둘째 그림은 뾰족한 곳이 몇 군데인가요?","asset":{"type":"shape_row","shapes":["sq","tri","cir","sq"],"mark":2},"options":[{"t":"3군데","correct":true},{"t":"4군데","mis":"M1-2-u3-X04"},{"t":"없어요","mis":"M1-2-u3-X05"}],"explanation":["표시한 것은 세모 모양이에요.","세모의 뾰족한 곳은 세 군데예요.","모양을 먼저 알아낸 다음 세어야 해요."],"seq":7}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_b#8','math',1,2,'u3','review','g1_2_math_u3_review_b','unit_review','M1-2-u3-C2',2,'ox','auto','세모 모양은 곧은 선 3개로 둘러싸여 있어요.',ARRAY['M1-2-u3-X05']::text[],false,'{"concept":"M1-2-u3-C2","difficulty":2,"kind":"ox","stem":"세모 모양은 곧은 선 3개로 둘러싸여 있어요.","reason_options":[{"t":"세모의 테두리는 곧은 선 세 개가 만나니까","correct":true},{"t":"세모에는 굽은 선도 하나 있으니까","mis":"M1-2-u3-X05"}],"answer":"O","explanation":["세모의 테두리를 손가락으로 따라가 보세요.","곧은 선 세 개가 세 군데에서 꺾여요.","굽은 곳은 하나도 없어요."],"seq":8}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_b#9','math',1,2,'u3','review','g1_2_math_u3_review_b','unit_review','M1-2-u3-C2',3,'sa','auto','그림에서 굽은 선으로만 이어진 모양은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"concept":"M1-2-u3-C2","difficulty":3,"kind":"sa","stem":"그림에서 굽은 선으로만 이어진 모양은 모두 몇 개인가요? 숫자로 쓰세요.","asset":{"type":"shape_row","shapes":["cir","tri","cir","sq","cir"]},"answer":["3"],"explanation":["굽은 선으로만 이어진 모양은 동그라미예요.","동그라미는 3개예요.","네모와 세모는 곧은 선이 있으니 세지 않아요."],"seq":9}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_b#10','math',1,2,'u3','review','g1_2_math_u3_review_b','unit_review','M1-2-u3-C3',1,'mc','auto','집 그림에 쓴 세모 모양은 몇 개인가요?',ARRAY['M1-2-u3-X06','M1-2-u3-X07']::text[],true,'{"concept":"M1-2-u3-C3","difficulty":1,"kind":"mc","stem":"집 그림에 쓴 세모 모양은 몇 개인가요?","asset":{"type":"shape_art","parts":[{"shape":"sq","n":3},{"shape":"tri","n":3},{"shape":"cir","n":2}],"name":"집"},"options":[{"t":"3","correct":true},{"t":"2","mis":"M1-2-u3-X06"},{"t":"4","mis":"M1-2-u3-X07"}],"explanation":["세모만 골라 하나씩 짚어요.","세모는 3개예요.","센 것에 표시하면 두 번 세지 않아요."],"variant_rule":{"art":{"n":[2,5],"ask":"tri"}},"seq":10}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_b#11','math',1,2,'u3','review','g1_2_math_u3_review_b','unit_review','M1-2-u3-C3',2,'sa','auto','자동차 그림에 쓴 모양은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"concept":"M1-2-u3-C3","difficulty":2,"kind":"sa","stem":"자동차 그림에 쓴 모양은 모두 몇 개인가요? 숫자로 쓰세요.","asset":{"type":"shape_art","parts":[{"shape":"sq","n":4},{"shape":"tri","n":1},{"shape":"cir","n":4}],"name":"자동차"},"answer":["9"],"explanation":["네모 4개, 세모 1개, 동그라미 4개예요.","4 + 1 + 4 = 9개예요.","종류별로 센 다음 모두 더해요."],"variant_rule":{"art":{"n":[1,5],"ask":"total"}},"seq":11}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_b#12','math',1,2,'u3','review','g1_2_math_u3_review_b','unit_review','M1-2-u3-C3',3,'mc','auto','눈사람 그림에서 가장 많이 쓴 모양은 무엇인가요?',ARRAY['M1-2-u3-X06']::text[],false,'{"concept":"M1-2-u3-C3","difficulty":3,"kind":"mc","stem":"눈사람 그림에서 가장 많이 쓴 모양은 무엇인가요?","asset":{"type":"shape_art","parts":[{"shape":"sq","n":1},{"shape":"tri","n":2},{"shape":"cir","n":5}],"name":"눈사람"},"options":[{"t":"동그라미 모양","correct":true},{"t":"네모 모양","mis":"M1-2-u3-X06"},{"t":"세모 모양","mis":"M1-2-u3-X06"}],"explanation":["네모 1개, 세모 2개, 동그라미 5개예요.","가장 많은 것은 동그라미 모양이에요.","종류별로 센 다음 수를 견줘요."],"seq":12}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_b#13','math',1,2,'u3','review','g1_2_math_u3_review_b','unit_review','M1-2-u3-C3',4,'error','auto','친구가 집 그림의 세모를 세어 보고 4개라고 했어요. 왜 틀렸을까요?',ARRAY['M1-2-u3-X06','M1-2-u3-X07','M1-2-u3-X01']::text[],false,'{"concept":"M1-2-u3-C3","difficulty":4,"kind":"error","stem":"친구가 집 그림의 세모를 세어 보고 4개라고 했어요. 왜 틀렸을까요?","asset":{"type":"shape_art","parts":[{"shape":"sq","n":3},{"shape":"tri","n":5},{"shape":"cir","n":2}],"name":"집"},"options":[{"t":"겹쳐 놓인 세모 하나를 빠뜨리고 세었어요.","correct":true,"mis_target":"M1-2-u3-X06"},{"t":"같은 세모를 두 번 세었어요.","mis":"M1-2-u3-X07"},{"t":"색깔이 다른 세모는 세면 안 되니까요.","mis":"M1-2-u3-X01"}],"explanation":["그림에는 세모가 5개 있어요.","겹친 곳에 숨은 세모를 빠뜨려서 4개가 되었어요.","센 모양에 표시를 하면 빠뜨리지 않아요."],"seq":13}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_b#14','math',1,2,'u3','review','g1_2_math_u3_review_b','unit_review','M1-2-u3-C4',1,'mc','auto','시계를 보세요. 몇 시인가요?',ARRAY['M1-2-u3-X08','M1-2-u3-X09']::text[],true,'{"concept":"M1-2-u3-C4","difficulty":1,"kind":"mc","stem":"시계를 보세요. 몇 시인가요?","asset":{"type":"clock","h":8,"m":0},"options":[{"t":"8시","correct":true},{"t":"12시","mis":"M1-2-u3-X08"},{"t":"9시","mis":"M1-2-u3-X09"}],"explanation":["짧은바늘이 8을 가리키고, 긴바늘이 12를 가리켜요.","그래서 8시예요.","긴바늘이 12를 가리키면 「몇 시」예요."],"variant_rule":{"time":{"hours":[1,12],"half":"oclock"}},"seq":14}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_b#15','math',1,2,'u3','review','g1_2_math_u3_review_b','unit_review','M1-2-u3-C4',1,'sa','auto','시계를 보세요. 몇 시인가요? ‘○시’로 쓰세요.','{}'::text[],true,'{"concept":"M1-2-u3-C4","difficulty":1,"kind":"sa","stem":"시계를 보세요. 몇 시인가요? ‘○시’로 쓰세요.","asset":{"type":"clock","h":2,"m":0},"answer":["2시","2"],"explanation":["짧은바늘이 2를 가리켜요.","긴바늘은 12를 가리키니 2시예요.","짧은바늘부터 읽어요."],"variant_rule":{"time":{"hours":[1,12],"half":"oclock"}},"seq":15}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_b#16','math',1,2,'u3','review','g1_2_math_u3_review_b','unit_review','M1-2-u3-C4',2,'blank','auto','지호는 (        )에 아침밥을 먹었어요. 시계를 보고 답하세요.',ARRAY['M1-2-u3-X08','M1-2-u3-X09']::text[],true,'{"concept":"M1-2-u3-C4","difficulty":2,"kind":"blank","stem":"지호는 (        )에 아침밥을 먹었어요. 시계를 보고 답하세요.","asset":{"type":"clock","h":7,"m":0},"options":[{"t":"7시","correct":true},{"t":"12시","mis":"M1-2-u3-X08"},{"t":"8시","mis":"M1-2-u3-X09"}],"explanation":["짧은바늘이 7을 가리켜요.","긴바늘이 12에 있으니 7시예요.","짧은바늘이 지나온 수를 읽어요."],"variant_rule":{"time":{"hours":[1,12],"half":"oclock"}},"seq":16}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_b#17','math',1,2,'u3','review','g1_2_math_u3_review_b','unit_review','M1-2-u3-C4',3,'error','auto','친구가 이 시계를 보고 12시라고 읽었어요. 왜 틀렸을까요?',ARRAY['M1-2-u3-X08','M1-2-u3-X10']::text[],false,'{"concept":"M1-2-u3-C4","difficulty":3,"kind":"error","stem":"친구가 이 시계를 보고 12시라고 읽었어요. 왜 틀렸을까요?","asset":{"type":"clock","h":7,"m":0},"options":[{"t":"긴바늘이 가리키는 수를 시로 읽었어요.","correct":true,"mis_target":"M1-2-u3-X08"},{"t":"짧은바늘이 없어서 읽을 수 없어요.","mis":"M1-2-u3-X08"},{"t":"긴바늘이 6을 가리켜서 30분이에요.","mis":"M1-2-u3-X10"}],"explanation":["짧은바늘은 7을 가리키고 있어요.","긴바늘 12를 시로 읽어서 12시가 되었어요.","시는 언제나 짧은바늘이 알려 줘요."],"seq":17}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_b#18','math',1,2,'u3','review','g1_2_math_u3_review_b','unit_review','M1-2-u3-C5',1,'mc','auto','시계를 보세요. 몇 시 몇 분인가요?',ARRAY['M1-2-u3-X09','M1-2-u3-X10']::text[],true,'{"concept":"M1-2-u3-C5","difficulty":1,"kind":"mc","stem":"시계를 보세요. 몇 시 몇 분인가요?","asset":{"type":"clock","h":7,"m":30},"options":[{"t":"7시 30분","correct":true},{"t":"8시 30분","mis":"M1-2-u3-X09"},{"t":"7시 6분","mis":"M1-2-u3-X10"}],"explanation":["짧은바늘은 7과 8 사이, 긴바늘은 6을 가리켜요.","그래서 7시 30분이에요.","긴바늘이 6이면 30분이에요."],"variant_rule":{"time":{"hours":[1,12],"half":"half"}},"seq":18}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_b#19','math',1,2,'u3','review','g1_2_math_u3_review_b','unit_review','M1-2-u3-C5',2,'sa','auto','시계를 보세요. 몇 시 몇 분인가요? ‘○시 30분’으로 쓰세요.','{}'::text[],true,'{"concept":"M1-2-u3-C5","difficulty":2,"kind":"sa","stem":"시계를 보세요. 몇 시 몇 분인가요? ‘○시 30분’으로 쓰세요.","asset":{"type":"clock","h":9,"m":30},"answer":["9시 30분","9시30분"],"explanation":["짧은바늘이 9를 지나 10로 가는 중이에요.","긴바늘이 6이니 9시 30분이에요.","짧은바늘이 지나온 수를 읽어요."],"variant_rule":{"time":{"hours":[1,12],"half":"half"}},"seq":19}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_b#20','math',1,2,'u3','review','g1_2_math_u3_review_b','unit_review','M1-2-u3-C5',2,'ox','auto','이 시계는 7시 30분이에요.',ARRAY['M1-2-u3-X09']::text[],false,'{"concept":"M1-2-u3-C5","difficulty":2,"kind":"ox","stem":"이 시계는 7시 30분이에요.","asset":{"type":"clock","h":6,"m":30},"reason_options":[{"t":"짧은바늘이 지나온 수는 6이니까","correct":true},{"t":"가까운 다음 수를 읽어야 하니까","mis":"M1-2-u3-X09"}],"answer":"X","explanation":["짧은바늘은 6과 7 사이에 있어요.","긴바늘은 6이니 6시 30분이에요.","짧은바늘은 지나온 수, 긴바늘 6은 30분이에요."],"seq":20}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_b#21','math',1,2,'u3','review','g1_2_math_u3_review_b','unit_review','M1-2-u3-C5',3,'error','auto','친구가 이 시계를 ‘3시 30분’이라고 읽었어요. 왜 틀렸을까요?',ARRAY['M1-2-u3-X09','M1-2-u3-X10','M1-2-u3-X08']::text[],true,'{"concept":"M1-2-u3-C5","difficulty":3,"kind":"error","stem":"친구가 이 시계를 ‘3시 30분’이라고 읽었어요. 왜 틀렸을까요?","asset":{"type":"clock","h":2,"m":30},"options":[{"t":"짧은바늘이 2와 3 사이인데 뒤의 수를 읽었어요.","correct":true,"mis_target":"M1-2-u3-X09"},{"t":"긴바늘이 6이라 30분이 아니에요.","mis":"M1-2-u3-X10"},{"t":"짧은바늘과 긴바늘을 바꿔 읽었어요.","mis":"M1-2-u3-X08"}],"explanation":["짧은바늘이 2를 지나 3로 가는 중이에요.","지나온 수를 읽어야 하니 2시 30분이에요.","가까워 보인다고 다음 수를 읽으면 안 돼요."],"variant_rule":{"time":{"hours":[1,12],"half":"half"}},"seq":21}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_b#22','math',1,2,'u3','review','g1_2_math_u3_review_b','unit_review','M1-2-u3-C6',2,'mc','auto','7시 30분을 시계에 나타내려면 긴바늘을 어디에 그려야 하나요?',ARRAY['M1-2-u3-X10','M1-2-u3-X08']::text[],false,'{"concept":"M1-2-u3-C6","difficulty":2,"kind":"mc","stem":"7시 30분을 시계에 나타내려면 긴바늘을 어디에 그려야 하나요?","asset":{"type":"clock","h":7,"m":30,"hands":"none"},"options":[{"t":"6","correct":true},{"t":"12","mis":"M1-2-u3-X10"},{"t":"7","mis":"M1-2-u3-X08"}],"explanation":["30분이면 긴바늘이 반 바퀴 돌아요.","반 바퀴는 6이에요.","짧은바늘은 7과 8 사이에 그려요."],"seq":22}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_b#23','math',1,2,'u3','review','g1_2_math_u3_review_b','unit_review','M1-2-u3-C6',3,'blank','auto','8시 30분을 나타내려면 짧은바늘을 8과 (        ) 사이에 그려요.',ARRAY['M1-2-u3-X09','M1-2-u3-X10']::text[],false,'{"concept":"M1-2-u3-C6","difficulty":3,"kind":"blank","stem":"8시 30분을 나타내려면 짧은바늘을 8과 (        ) 사이에 그려요.","asset":{"type":"clock","h":8,"m":30,"hands":"none"},"options":[{"t":"9","correct":true},{"t":"7","mis":"M1-2-u3-X09"},{"t":"6","mis":"M1-2-u3-X10"}],"explanation":["30분은 두 수의 가운데쯤이에요.","8시 30분이니 8과 9 사이예요.","6은 긴바늘이 가는 자리예요."],"seq":23}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_b#24','math',1,2,'u3','review','g1_2_math_u3_review_b','unit_review','M1-2-u3-C6',4,'mc','auto','도윤는 7시에 아침밥을 먹기 시작했어요. 이때 시계의 두 바늘은 어떻게 놓여 있나요?',ARRAY['M1-2-u3-X08','M1-2-u3-X10']::text[],false,'{"concept":"M1-2-u3-C6","difficulty":4,"kind":"mc","stem":"도윤는 7시에 아침밥을 먹기 시작했어요. 이때 시계의 두 바늘은 어떻게 놓여 있나요?","options":[{"t":"짧은바늘은 7, 긴바늘은 12","correct":true},{"t":"짧은바늘은 12, 긴바늘은 7","mis":"M1-2-u3-X08"},{"t":"짧은바늘은 7과 8 사이, 긴바늘은 6","mis":"M1-2-u3-X10"}],"explanation":["「몇 시」는 긴바늘이 12에 있어요.","짧은바늘이 7을 가리켜야 7시예요.","두 바늘을 바꾸면 12시쯤이 되어 버려요."],"seq":24}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_b#25','math',1,2,'u3','review','g1_2_math_u3_review_b','unit_review','M1-2-u3-C6',4,'essay','teacher','점심을 먹는 시각이 12시예요. 이 시각을 시계에 그린다면 짧은바늘과 긴바늘을 각각 어디에 그려야 하는지 쓰고, 그 까닭도 쓰세요.','{}'::text[],false,'{"concept":"M1-2-u3-C6","difficulty":4,"kind":"essay","stem":"점심을 먹는 시각이 12시예요. 이 시각을 시계에 그린다면 짧은바늘과 긴바늘을 각각 어디에 그려야 하는지 쓰고, 그 까닭도 쓰세요.","asset":{"type":"clock","h":12,"m":0,"hands":"none"},"answer_guide":"짧은바늘 「12」 + 긴바늘 「12」 + 까닭(긴바늘이 12이면 몇 시 / 짧은바늘은 그 수를 가리킨다)이 함께 있으면 정답. 두 바늘 자리만 맞고 까닭이 없으면 반만 맞음. 두 바늘 길이를 바꿔 쓰면 틀림.","explanation":["긴바늘은 12에 그려요 — 「몇 시」니까요.","짧은바늘은 12에 그려요.","짧은바늘을 먼저 그리고 긴바늘을 길게 덧그려요."],"seq":25}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_c#1','math',1,2,'u3','review','g1_2_math_u3_review_c','unit_review','M1-2-u3-C1',1,'mc','auto','그림을 보세요. 동그라미 모양은 몇 개인가요?',ARRAY['M1-2-u3-X07','M1-2-u3-X06']::text[],true,'{"concept":"M1-2-u3-C1","difficulty":1,"kind":"mc","stem":"그림을 보세요. 동그라미 모양은 몇 개인가요?","asset":{"type":"shape_row","shapes":["cir","sq","cir","tri","cir","sq"]},"options":[{"t":"3","correct":true},{"t":"4","mis":"M1-2-u3-X07"},{"t":"2","mis":"M1-2-u3-X06"}],"explanation":["동그라미 모양만 골라 손으로 짚어 보세요.","동그라미는 3개예요.","센 것에 표시를 하면 두 번 세지 않아요."],"variant_rule":{"shapes":{"len":[4,6],"ask":"count","target":"cir"}},"seq":1}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_c#2','math',1,2,'u3','review','g1_2_math_u3_review_c','unit_review','M1-2-u3-C1',1,'sa','auto','그림을 보세요. 네모 모양은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"concept":"M1-2-u3-C1","difficulty":1,"kind":"sa","stem":"그림을 보세요. 네모 모양은 몇 개인가요? 숫자로 쓰세요.","asset":{"type":"shape_row","shapes":["sq","tri","sq","cir","sq","tri"]},"answer":["3"],"explanation":["네모만 골라 세어요.","네모는 3개예요.","세모와 동그라미는 세지 않아요."],"variant_rule":{"shapes":{"len":[4,6],"ask":"count","target":"sq"}},"seq":2}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_c#3','math',1,2,'u3','review','g1_2_math_u3_review_c','unit_review','M1-2-u3-C1',2,'blank','auto','삼각김밥과 피자 조각은 모두 (        ) 모양이에요.',ARRAY['M1-2-u3-X02']::text[],false,'{"concept":"M1-2-u3-C1","difficulty":2,"kind":"blank","stem":"삼각김밥과 피자 조각은 모두 (        ) 모양이에요.","options":[{"t":"세모","correct":true},{"t":"네모","mis":"M1-2-u3-X02"},{"t":"동그라미","mis":"M1-2-u3-X02"}],"explanation":["삼각김밥과 피자 조각의 테두리를 따라가 보세요.","둘 다 곧은 선 세 개로 이어져 세모 모양이에요.","크기가 달라도 모양 이름은 같아요."],"seq":3}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_c#4','math',1,2,'u3','review','g1_2_math_u3_review_c','unit_review','M1-2-u3-C1',2,'match','auto','물건과 알맞은 모양을 줄로 이어 보세요.','{}'::text[],false,'{"concept":"M1-2-u3-C1","difficulty":2,"kind":"match","stem":"물건과 알맞은 모양을 줄로 이어 보세요.","pairs":[{"l":"🚪 문","r":"네모 모양"},{"l":"📐 삼각자","r":"세모 모양"},{"l":"🍪 쿠키","r":"동그라미 모양"}],"explanation":["물건의 테두리 생김새를 봐요.","문은 네모, 삼각자는 세모, 쿠키는 동그라미예요.","색깔이나 크기는 모양과 상관이 없어요."],"seq":4}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_c#5','math',1,2,'u3','review','g1_2_math_u3_review_c','unit_review','M1-2-u3-C1',3,'error','auto','세 친구가 세모 모양 물건을 하나씩 골랐어요. 잘못 고른 친구는 누구인가요?',ARRAY['M1-2-u3-X02','M1-2-u3-X01']::text[],false,'{"concept":"M1-2-u3-C1","difficulty":3,"kind":"error","stem":"세 친구가 세모 모양 물건을 하나씩 골랐어요. 잘못 고른 친구는 누구인가요?","options":[{"t":"문을 고른 서준","correct":true,"mis_target":"M1-2-u3-X02"},{"t":"삼각김밥을 고른 유나","mis":"M1-2-u3-X02"},{"t":"피자 조각을 고른 도윤","mis":"M1-2-u3-X01"}],"explanation":["삼각김밥과 피자 조각은 곧은 선 세 개로 둘러싸여 있어요.","문은 곧은 선 네 개로 이어진 네모 모양이에요.","세모인지 볼 때는 뾰족한 곳이 세 군데인지 확인해요."],"seq":5}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_c#6','math',1,2,'u3','review','g1_2_math_u3_review_c','unit_review','M1-2-u3-C2',1,'sa','auto','세모 모양은 곧은 선이 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"concept":"M1-2-u3-C2","difficulty":1,"kind":"sa","stem":"세모 모양은 곧은 선이 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["세모의 테두리를 따라가며 선을 세어요.","곧은 선이 3개예요.","뾰족한 곳도 3군데예요."],"seq":6}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_c#7','math',1,2,'u3','review','g1_2_math_u3_review_c','unit_review','M1-2-u3-C2',1,'mc','auto','점선으로 표시한 둘째 그림은 뾰족한 곳이 몇 군데인가요?',ARRAY['M1-2-u3-X05']::text[],false,'{"concept":"M1-2-u3-C2","difficulty":1,"kind":"mc","stem":"점선으로 표시한 둘째 그림은 뾰족한 곳이 몇 군데인가요?","asset":{"type":"shape_row","shapes":["tri","cir","sq","tri"],"mark":2},"options":[{"t":"없어요","correct":true},{"t":"3군데","mis":"M1-2-u3-X05"},{"t":"4군데","mis":"M1-2-u3-X05"}],"explanation":["표시한 것은 동그라미 모양이에요.","동그라미는 굽은 선으로만 이어져 뾰족한 곳이 없어요.","모양을 먼저 알아낸 다음 세어야 해요."],"seq":7}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_c#8','math',1,2,'u3','review','g1_2_math_u3_review_c','unit_review','M1-2-u3-C2',2,'ox','auto','네모 모양은 뾰족한 곳이 3군데예요.',ARRAY['M1-2-u3-X04']::text[],false,'{"concept":"M1-2-u3-C2","difficulty":2,"kind":"ox","stem":"네모 모양은 뾰족한 곳이 3군데예요.","reason_options":[{"t":"네모는 곧은 선 네 개가 만나 뾰족한 곳이 네 군데니까","correct":true},{"t":"네모는 세모보다 뾰족한 곳이 하나 적으니까","mis":"M1-2-u3-X04"}],"answer":"X","explanation":["네모의 꼭짓점을 하나씩 짚으며 세어 보세요.","곧은 선 네 개가 만나 뾰족한 곳은 네 군데예요.","3군데는 세모예요."],"seq":8}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_c#9','math',1,2,'u3','review','g1_2_math_u3_review_c','unit_review','M1-2-u3-C2',3,'sa','auto','그림에서 곧은 선으로 둘러싸인 모양은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"concept":"M1-2-u3-C2","difficulty":3,"kind":"sa","stem":"그림에서 곧은 선으로 둘러싸인 모양은 모두 몇 개인가요? 숫자로 쓰세요.","asset":{"type":"shape_row","shapes":["tri","sq","cir","tri","sq","sq"]},"answer":["5"],"explanation":["곧은 선으로 둘러싸인 모양은 네모와 세모예요.","네모 3개와 세모 2개를 더하면 5개예요.","동그라미는 세지 않아요."],"seq":9}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_c#10','math',1,2,'u3','review','g1_2_math_u3_review_c','unit_review','M1-2-u3-C3',1,'mc','auto','꽃 그림에 쓴 동그라미 모양은 몇 개인가요?',ARRAY['M1-2-u3-X06','M1-2-u3-X07']::text[],true,'{"concept":"M1-2-u3-C3","difficulty":1,"kind":"mc","stem":"꽃 그림에 쓴 동그라미 모양은 몇 개인가요?","asset":{"type":"shape_art","parts":[{"shape":"sq","n":2},{"shape":"tri","n":3},{"shape":"cir","n":5}],"name":"꽃"},"options":[{"t":"5","correct":true},{"t":"4","mis":"M1-2-u3-X06"},{"t":"6","mis":"M1-2-u3-X07"}],"explanation":["동그라미만 골라 하나씩 짚어요.","동그라미는 5개예요.","센 것에 표시하면 두 번 세지 않아요."],"variant_rule":{"art":{"n":[2,5],"ask":"cir"}},"seq":10}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_c#11','math',1,2,'u3','review','g1_2_math_u3_review_c','unit_review','M1-2-u3-C3',2,'sa','auto','나무 그림에 쓴 모양은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"concept":"M1-2-u3-C3","difficulty":2,"kind":"sa","stem":"나무 그림에 쓴 모양은 모두 몇 개인가요? 숫자로 쓰세요.","asset":{"type":"shape_art","parts":[{"shape":"sq","n":2},{"shape":"tri","n":3},{"shape":"cir","n":3}],"name":"나무"},"answer":["8"],"explanation":["네모 2개, 세모 3개, 동그라미 3개예요.","2 + 3 + 3 = 8개예요.","종류별로 센 다음 모두 더해요."],"variant_rule":{"art":{"n":[1,5],"ask":"total"}},"seq":11}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_c#12','math',1,2,'u3','review','g1_2_math_u3_review_c','unit_review','M1-2-u3-C3',3,'mc','auto','성 그림에서 가장 많이 쓴 모양은 무엇인가요?',ARRAY['M1-2-u3-X06']::text[],false,'{"concept":"M1-2-u3-C3","difficulty":3,"kind":"mc","stem":"성 그림에서 가장 많이 쓴 모양은 무엇인가요?","asset":{"type":"shape_art","parts":[{"shape":"sq","n":3},{"shape":"tri","n":5},{"shape":"cir","n":2}],"name":"성"},"options":[{"t":"세모 모양","correct":true},{"t":"네모 모양","mis":"M1-2-u3-X06"},{"t":"동그라미 모양","mis":"M1-2-u3-X06"}],"explanation":["네모 3개, 세모 5개, 동그라미 2개예요.","가장 많은 것은 세모 모양이에요.","종류별로 센 다음 수를 견줘요."],"seq":12}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_c#13','math',1,2,'u3','review','g1_2_math_u3_review_c','unit_review','M1-2-u3-C3',4,'error','auto','친구가 눈사람 그림의 동그라미를 세어 보고 5개라고 했어요. 왜 틀렸을까요?',ARRAY['M1-2-u3-X06','M1-2-u3-X07','M1-2-u3-X01']::text[],false,'{"concept":"M1-2-u3-C3","difficulty":4,"kind":"error","stem":"친구가 눈사람 그림의 동그라미를 세어 보고 5개라고 했어요. 왜 틀렸을까요?","asset":{"type":"shape_art","parts":[{"shape":"sq","n":2},{"shape":"tri","n":1},{"shape":"cir","n":6}],"name":"눈사람"},"options":[{"t":"겹쳐 놓인 동그라미 하나를 빠뜨리고 세었어요.","correct":true,"mis_target":"M1-2-u3-X06"},{"t":"같은 동그라미를 두 번 세었어요.","mis":"M1-2-u3-X07"},{"t":"색깔이 다른 동그라미는 세면 안 되니까요.","mis":"M1-2-u3-X01"}],"explanation":["그림에는 동그라미가 6개 있어요.","겹친 곳에 숨은 동그라미를 빠뜨려서 5개가 되었어요.","센 모양에 표시를 하면 빠뜨리지 않아요."],"seq":13}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_c#14','math',1,2,'u3','review','g1_2_math_u3_review_c','unit_review','M1-2-u3-C4',1,'mc','auto','시계를 보세요. 몇 시인가요?',ARRAY['M1-2-u3-X08','M1-2-u3-X09']::text[],true,'{"concept":"M1-2-u3-C4","difficulty":1,"kind":"mc","stem":"시계를 보세요. 몇 시인가요?","asset":{"type":"clock","h":10,"m":0},"options":[{"t":"10시","correct":true},{"t":"12시","mis":"M1-2-u3-X08"},{"t":"11시","mis":"M1-2-u3-X09"}],"explanation":["짧은바늘이 10을 가리키고, 긴바늘이 12를 가리켜요.","그래서 10시예요.","긴바늘이 12를 가리키면 「몇 시」예요."],"variant_rule":{"time":{"hours":[1,12],"half":"oclock"}},"seq":14}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_c#15','math',1,2,'u3','review','g1_2_math_u3_review_c','unit_review','M1-2-u3-C4',1,'sa','auto','시계를 보세요. 몇 시인가요? ‘○시’로 쓰세요.','{}'::text[],true,'{"concept":"M1-2-u3-C4","difficulty":1,"kind":"sa","stem":"시계를 보세요. 몇 시인가요? ‘○시’로 쓰세요.","asset":{"type":"clock","h":6,"m":0},"answer":["6시","6"],"explanation":["짧은바늘이 6을 가리켜요.","긴바늘은 12를 가리키니 6시예요.","짧은바늘부터 읽어요."],"variant_rule":{"time":{"hours":[1,12],"half":"oclock"}},"seq":15}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_c#16','math',1,2,'u3','review','g1_2_math_u3_review_c','unit_review','M1-2-u3-C4',2,'blank','auto','나윤는 (        )에 놀이터에서 놀았어요. 시계를 보고 답하세요.',ARRAY['M1-2-u3-X08','M1-2-u3-X09']::text[],true,'{"concept":"M1-2-u3-C4","difficulty":2,"kind":"blank","stem":"나윤는 (        )에 놀이터에서 놀았어요. 시계를 보고 답하세요.","asset":{"type":"clock","h":3,"m":0},"options":[{"t":"3시","correct":true},{"t":"12시","mis":"M1-2-u3-X08"},{"t":"4시","mis":"M1-2-u3-X09"}],"explanation":["짧은바늘이 3을 가리켜요.","긴바늘이 12에 있으니 3시예요.","짧은바늘이 지나온 수를 읽어요."],"variant_rule":{"time":{"hours":[1,12],"half":"oclock"}},"seq":16}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_c#17','math',1,2,'u3','review','g1_2_math_u3_review_c','unit_review','M1-2-u3-C4',3,'error','auto','친구가 이 시계를 보고 12시라고 읽었어요. 왜 틀렸을까요?',ARRAY['M1-2-u3-X08','M1-2-u3-X10']::text[],false,'{"concept":"M1-2-u3-C4","difficulty":3,"kind":"error","stem":"친구가 이 시계를 보고 12시라고 읽었어요. 왜 틀렸을까요?","asset":{"type":"clock","h":1,"m":0},"options":[{"t":"긴바늘이 가리키는 수를 시로 읽었어요.","correct":true,"mis_target":"M1-2-u3-X08"},{"t":"짧은바늘이 없어서 읽을 수 없어요.","mis":"M1-2-u3-X08"},{"t":"긴바늘이 6을 가리켜서 30분이에요.","mis":"M1-2-u3-X10"}],"explanation":["짧은바늘은 1을 가리키고 있어요.","긴바늘 12를 시로 읽어서 12시가 되었어요.","시는 언제나 짧은바늘이 알려 줘요."],"seq":17}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_c#18','math',1,2,'u3','review','g1_2_math_u3_review_c','unit_review','M1-2-u3-C5',1,'mc','auto','시계를 보세요. 몇 시 몇 분인가요?',ARRAY['M1-2-u3-X09','M1-2-u3-X10']::text[],true,'{"concept":"M1-2-u3-C5","difficulty":1,"kind":"mc","stem":"시계를 보세요. 몇 시 몇 분인가요?","asset":{"type":"clock","h":10,"m":30},"options":[{"t":"10시 30분","correct":true},{"t":"11시 30분","mis":"M1-2-u3-X09"},{"t":"10시 6분","mis":"M1-2-u3-X10"}],"explanation":["짧은바늘은 10과 11 사이, 긴바늘은 6을 가리켜요.","그래서 10시 30분이에요.","긴바늘이 6이면 30분이에요."],"variant_rule":{"time":{"hours":[1,12],"half":"half"}},"seq":18}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_c#19','math',1,2,'u3','review','g1_2_math_u3_review_c','unit_review','M1-2-u3-C5',2,'sa','auto','시계를 보세요. 몇 시 몇 분인가요? ‘○시 30분’으로 쓰세요.','{}'::text[],true,'{"concept":"M1-2-u3-C5","difficulty":2,"kind":"sa","stem":"시계를 보세요. 몇 시 몇 분인가요? ‘○시 30분’으로 쓰세요.","asset":{"type":"clock","h":1,"m":30},"answer":["1시 30분","1시30분"],"explanation":["짧은바늘이 1을 지나 2로 가는 중이에요.","긴바늘이 6이니 1시 30분이에요.","짧은바늘이 지나온 수를 읽어요."],"variant_rule":{"time":{"hours":[1,12],"half":"half"}},"seq":19}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_c#20','math',1,2,'u3','review','g1_2_math_u3_review_c','unit_review','M1-2-u3-C5',2,'ox','auto','이 시계는 8시 6분이에요.',ARRAY['M1-2-u3-X10']::text[],false,'{"concept":"M1-2-u3-C5","difficulty":2,"kind":"ox","stem":"이 시계는 8시 6분이에요.","asset":{"type":"clock","h":8,"m":30},"reason_options":[{"t":"긴바늘이 6을 가리키면 30분이니까","correct":true},{"t":"긴바늘이 가리키는 수가 그대로 분이니까","mis":"M1-2-u3-X10"}],"answer":"X","explanation":["짧은바늘은 8과 9 사이에 있어요.","긴바늘은 6이니 8시 30분이에요.","짧은바늘은 지나온 수, 긴바늘 6은 30분이에요."],"seq":20}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_c#21','math',1,2,'u3','review','g1_2_math_u3_review_c','unit_review','M1-2-u3-C5',3,'error','auto','친구가 이 시계를 ‘10시 30분’이라고 읽었어요. 왜 틀렸을까요?',ARRAY['M1-2-u3-X09','M1-2-u3-X10','M1-2-u3-X08']::text[],true,'{"concept":"M1-2-u3-C5","difficulty":3,"kind":"error","stem":"친구가 이 시계를 ‘10시 30분’이라고 읽었어요. 왜 틀렸을까요?","asset":{"type":"clock","h":9,"m":30},"options":[{"t":"짧은바늘이 9와 10 사이인데 뒤의 수를 읽었어요.","correct":true,"mis_target":"M1-2-u3-X09"},{"t":"긴바늘이 6이라 30분이 아니에요.","mis":"M1-2-u3-X10"},{"t":"짧은바늘과 긴바늘을 바꿔 읽었어요.","mis":"M1-2-u3-X08"}],"explanation":["짧은바늘이 9를 지나 10로 가는 중이에요.","지나온 수를 읽어야 하니 9시 30분이에요.","가까워 보인다고 다음 수를 읽으면 안 돼요."],"variant_rule":{"time":{"hours":[1,12],"half":"half"}},"seq":21}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_c#22','math',1,2,'u3','review','g1_2_math_u3_review_c','unit_review','M1-2-u3-C6',2,'mc','auto','10시를 시계에 나타내려면 긴바늘을 어디에 그려야 하나요?',ARRAY['M1-2-u3-X10','M1-2-u3-X08']::text[],false,'{"concept":"M1-2-u3-C6","difficulty":2,"kind":"mc","stem":"10시를 시계에 나타내려면 긴바늘을 어디에 그려야 하나요?","asset":{"type":"clock","h":10,"m":0,"hands":"none"},"options":[{"t":"12","correct":true},{"t":"6","mis":"M1-2-u3-X10"},{"t":"10","mis":"M1-2-u3-X08"}],"explanation":["「몇 시」는 긴바늘이 12에 있어요.","그래서 긴바늘을 12에 그려요.","짧은바늘을 10에 그리면 10시가 돼요."],"seq":22}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_c#23','math',1,2,'u3','review','g1_2_math_u3_review_c','unit_review','M1-2-u3-C6',3,'blank','auto','9시 30분을 나타내려면 짧은바늘을 9와 (        ) 사이에 그려요.',ARRAY['M1-2-u3-X09','M1-2-u3-X10']::text[],false,'{"concept":"M1-2-u3-C6","difficulty":3,"kind":"blank","stem":"9시 30분을 나타내려면 짧은바늘을 9와 (        ) 사이에 그려요.","asset":{"type":"clock","h":9,"m":30,"hands":"none"},"options":[{"t":"10","correct":true},{"t":"8","mis":"M1-2-u3-X09"},{"t":"6","mis":"M1-2-u3-X10"}],"explanation":["30분은 두 수의 가운데쯤이에요.","9시 30분이니 9와 10 사이예요.","6은 긴바늘이 가는 자리예요."],"seq":23}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_c#24','math',1,2,'u3','review','g1_2_math_u3_review_c','unit_review','M1-2-u3-C6',4,'mc','auto','서아는 9시 30분에 책을 읽기 시작했어요. 이때 시계의 두 바늘은 어떻게 놓여 있나요?',ARRAY['M1-2-u3-X08','M1-2-u3-X09']::text[],false,'{"concept":"M1-2-u3-C6","difficulty":4,"kind":"mc","stem":"서아는 9시 30분에 책을 읽기 시작했어요. 이때 시계의 두 바늘은 어떻게 놓여 있나요?","options":[{"t":"짧은바늘은 9와 10 사이, 긴바늘은 6","correct":true},{"t":"짧은바늘은 6, 긴바늘은 9","mis":"M1-2-u3-X08"},{"t":"짧은바늘은 10과 11 사이, 긴바늘은 6","mis":"M1-2-u3-X09"}],"explanation":["30분이면 긴바늘은 6에 있어요.","짧은바늘은 9를 지나 10으로 가는 중이니 9와 10 사이예요.","짧은바늘이 시, 긴바늘이 분이에요."],"seq":24}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_c#25','math',1,2,'u3','review','g1_2_math_u3_review_c','unit_review','M1-2-u3-C6',4,'essay','teacher','간식을 먹는 시각이 4시 30분이에요. 이 시각을 시계에 그린다면 짧은바늘과 긴바늘을 각각 어디에 그려야 하는지 쓰고, 그 까닭도 쓰세요.','{}'::text[],false,'{"concept":"M1-2-u3-C6","difficulty":4,"kind":"essay","stem":"간식을 먹는 시각이 4시 30분이에요. 이 시각을 시계에 그린다면 짧은바늘과 긴바늘을 각각 어디에 그려야 하는지 쓰고, 그 까닭도 쓰세요.","asset":{"type":"clock","h":4,"m":30,"hands":"none"},"answer_guide":"짧은바늘 「4와 5 사이」 + 긴바늘 「6」 + 까닭(긴바늘이 6이면 30분 / 짧은바늘은 지나온 수를 읽는다)이 함께 있으면 정답. 두 바늘 자리만 맞고 까닭이 없으면 반만 맞음. 두 바늘 길이를 바꿔 쓰면 틀림.","explanation":["긴바늘은 6에 그려요 — 30분이니까요.","짧은바늘은 4와 5 사이에 그려요.","짧은바늘을 먼저 그리고 긴바늘을 길게 덧그려요."],"seq":25}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_d#1','math',1,2,'u3','review','g1_2_math_u3_review_d','unit_review','M1-2-u3-C1',1,'mc','auto','그림을 보세요. 세모 모양은 몇 개인가요?',ARRAY['M1-2-u3-X07','M1-2-u3-X06']::text[],true,'{"concept":"M1-2-u3-C1","difficulty":1,"kind":"mc","stem":"그림을 보세요. 세모 모양은 몇 개인가요?","asset":{"type":"shape_row","shapes":["tri","sq","tri","cir","tri"]},"options":[{"t":"3","correct":true},{"t":"4","mis":"M1-2-u3-X07"},{"t":"2","mis":"M1-2-u3-X06"}],"explanation":["세모 모양만 골라 손으로 짚어 보세요.","세모는 3개예요.","센 것에 표시를 하면 두 번 세지 않아요."],"variant_rule":{"shapes":{"len":[4,6],"ask":"count","target":"tri"}},"seq":1}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_d#2','math',1,2,'u3','review','g1_2_math_u3_review_d','unit_review','M1-2-u3-C1',1,'sa','auto','그림을 보세요. 동그라미 모양은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"concept":"M1-2-u3-C1","difficulty":1,"kind":"sa","stem":"그림을 보세요. 동그라미 모양은 몇 개인가요? 숫자로 쓰세요.","asset":{"type":"shape_row","shapes":["cir","tri","cir","sq"]},"answer":["2"],"explanation":["동그라미만 골라 세어요.","동그라미는 2개예요.","네모와 세모는 세지 않아요."],"variant_rule":{"shapes":{"len":[4,6],"ask":"count","target":"cir"}},"seq":2}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_d#3','math',1,2,'u3','review','g1_2_math_u3_review_d','unit_review','M1-2-u3-C1',2,'blank','auto','책과 문은 모두 (        ) 모양이에요.',ARRAY['M1-2-u3-X02']::text[],false,'{"concept":"M1-2-u3-C1","difficulty":2,"kind":"blank","stem":"책과 문은 모두 (        ) 모양이에요.","options":[{"t":"네모","correct":true},{"t":"세모","mis":"M1-2-u3-X02"},{"t":"동그라미","mis":"M1-2-u3-X02"}],"explanation":["책과 문의 테두리를 따라가 보세요.","둘 다 곧은 선 네 개로 이어져 네모 모양이에요.","크기가 달라도 모양 이름은 같아요."],"seq":3}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_d#4','math',1,2,'u3','review','g1_2_math_u3_review_d','unit_review','M1-2-u3-C1',2,'match','auto','물건과 알맞은 모양을 줄로 이어 보세요.','{}'::text[],false,'{"concept":"M1-2-u3-C1","difficulty":2,"kind":"match","stem":"물건과 알맞은 모양을 줄로 이어 보세요.","pairs":[{"l":"🖼️ 액자","r":"네모 모양"},{"l":"⛵ 돛","r":"세모 모양"},{"l":"🍩 도넛","r":"동그라미 모양"}],"explanation":["물건의 테두리 생김새를 봐요.","액자는 네모, 돛은 세모, 도넛은 동그라미예요.","색깔이나 크기는 모양과 상관이 없어요."],"seq":4}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_d#5','math',1,2,'u3','review','g1_2_math_u3_review_d','unit_review','M1-2-u3-C1',3,'error','auto','세 친구가 네모 모양 물건을 하나씩 골랐어요. 잘못 고른 친구는 누구인가요?',ARRAY['M1-2-u3-X02','M1-2-u3-X01']::text[],false,'{"concept":"M1-2-u3-C1","difficulty":3,"kind":"error","stem":"세 친구가 네모 모양 물건을 하나씩 골랐어요. 잘못 고른 친구는 누구인가요?","options":[{"t":"접시를 고른 하린","correct":true,"mis_target":"M1-2-u3-X02"},{"t":"책을 고른 시우","mis":"M1-2-u3-X02"},{"t":"액자를 고른 다온","mis":"M1-2-u3-X01"}],"explanation":["책과 액자는 곧은 선 네 개로 둘러싸여 있어요.","접시는 굽은 선으로 둥글게 이어진 동그라미 모양이에요.","네모인지 볼 때는 뾰족한 곳이 네 군데인지 확인해요."],"seq":5}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_d#6','math',1,2,'u3','review','g1_2_math_u3_review_d','unit_review','M1-2-u3-C2',1,'sa','auto','네모 모양은 뾰족한 곳이 몇 군데인가요? 숫자로 쓰세요.','{}'::text[],false,'{"concept":"M1-2-u3-C2","difficulty":1,"kind":"sa","stem":"네모 모양은 뾰족한 곳이 몇 군데인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["네모의 꼭짓점을 하나씩 짚어요.","뾰족한 곳이 4군데예요.","곧은 선도 4개예요."],"seq":6}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_d#7','math',1,2,'u3','review','g1_2_math_u3_review_d','unit_review','M1-2-u3-C2',1,'mc','auto','점선으로 표시한 셋째 그림은 뾰족한 곳이 몇 군데인가요?',ARRAY['M1-2-u3-X04','M1-2-u3-X05']::text[],false,'{"concept":"M1-2-u3-C2","difficulty":1,"kind":"mc","stem":"점선으로 표시한 셋째 그림은 뾰족한 곳이 몇 군데인가요?","asset":{"type":"shape_row","shapes":["cir","tri","sq","cir"],"mark":3},"options":[{"t":"4군데","correct":true},{"t":"3군데","mis":"M1-2-u3-X04"},{"t":"없어요","mis":"M1-2-u3-X05"}],"explanation":["표시한 것은 네모 모양이에요.","네모의 뾰족한 곳은 네 군데예요.","모양을 먼저 알아낸 다음 세어야 해요."],"seq":7}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_d#8','math',1,2,'u3','review','g1_2_math_u3_review_d','unit_review','M1-2-u3-C2',2,'ox','auto','세모를 눕혀 놓아도 뾰족한 곳은 3군데예요.',ARRAY['M1-2-u3-X03']::text[],false,'{"concept":"M1-2-u3-C2","difficulty":2,"kind":"ox","stem":"세모를 눕혀 놓아도 뾰족한 곳은 3군데예요.","reason_options":[{"t":"돌려 놓아도 생김새는 그대로니까","correct":true},{"t":"눕히면 다른 모양이 되니까","mis":"M1-2-u3-X03"}],"answer":"O","explanation":["세모 조각을 돌려 보세요.","방향이 바뀌어도 뾰족한 곳은 그대로 세 군데예요.","모양은 놓인 방향과 상관없어요."],"seq":8}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_d#9','math',1,2,'u3','review','g1_2_math_u3_review_d','unit_review','M1-2-u3-C2',3,'sa','auto','그림에서 굽은 선으로만 이어진 모양은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"concept":"M1-2-u3-C2","difficulty":3,"kind":"sa","stem":"그림에서 굽은 선으로만 이어진 모양은 모두 몇 개인가요? 숫자로 쓰세요.","asset":{"type":"shape_row","shapes":["sq","cir","cir","tri","cir"]},"answer":["3"],"explanation":["굽은 선으로만 이어진 모양은 동그라미예요.","동그라미는 3개예요.","네모와 세모는 곧은 선이 있으니 세지 않아요."],"seq":9}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_d#10','math',1,2,'u3','review','g1_2_math_u3_review_d','unit_review','M1-2-u3-C3',1,'mc','auto','기차 그림에 쓴 네모 모양은 몇 개인가요?',ARRAY['M1-2-u3-X06','M1-2-u3-X07']::text[],true,'{"concept":"M1-2-u3-C3","difficulty":1,"kind":"mc","stem":"기차 그림에 쓴 네모 모양은 몇 개인가요?","asset":{"type":"shape_art","parts":[{"shape":"sq","n":5},{"shape":"tri","n":2},{"shape":"cir","n":3}],"name":"기차"},"options":[{"t":"5","correct":true},{"t":"4","mis":"M1-2-u3-X06"},{"t":"6","mis":"M1-2-u3-X07"}],"explanation":["네모만 골라 하나씩 짚어요.","네모는 5개예요.","센 것에 표시하면 두 번 세지 않아요."],"variant_rule":{"art":{"n":[2,5],"ask":"sq"}},"seq":10}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_d#11','math',1,2,'u3','review','g1_2_math_u3_review_d','unit_review','M1-2-u3-C3',2,'sa','auto','강아지 그림에 쓴 모양은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"concept":"M1-2-u3-C3","difficulty":2,"kind":"sa","stem":"강아지 그림에 쓴 모양은 모두 몇 개인가요? 숫자로 쓰세요.","asset":{"type":"shape_art","parts":[{"shape":"sq","n":3},{"shape":"tri","n":2},{"shape":"cir","n":4}],"name":"강아지"},"answer":["9"],"explanation":["네모 3개, 세모 2개, 동그라미 4개예요.","3 + 2 + 4 = 9개예요.","종류별로 센 다음 모두 더해요."],"variant_rule":{"art":{"n":[1,5],"ask":"total"}},"seq":11}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_d#12','math',1,2,'u3','review','g1_2_math_u3_review_d','unit_review','M1-2-u3-C3',3,'mc','auto','로켓 그림에서 가장 많이 쓴 모양은 무엇인가요?',ARRAY['M1-2-u3-X06']::text[],false,'{"concept":"M1-2-u3-C3","difficulty":3,"kind":"mc","stem":"로켓 그림에서 가장 많이 쓴 모양은 무엇인가요?","asset":{"type":"shape_art","parts":[{"shape":"sq","n":4},{"shape":"tri","n":2},{"shape":"cir","n":1}],"name":"로켓"},"options":[{"t":"네모 모양","correct":true},{"t":"세모 모양","mis":"M1-2-u3-X06"},{"t":"동그라미 모양","mis":"M1-2-u3-X06"}],"explanation":["네모 4개, 세모 2개, 동그라미 1개예요.","가장 많은 것은 네모 모양이에요.","종류별로 센 다음 수를 견줘요."],"seq":12}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_d#13','math',1,2,'u3','review','g1_2_math_u3_review_d','unit_review','M1-2-u3-C3',4,'error','auto','친구가 배 그림의 네모를 세어 보고 4개라고 했어요. 왜 틀렸을까요?',ARRAY['M1-2-u3-X06','M1-2-u3-X07','M1-2-u3-X01']::text[],false,'{"concept":"M1-2-u3-C3","difficulty":4,"kind":"error","stem":"친구가 배 그림의 네모를 세어 보고 4개라고 했어요. 왜 틀렸을까요?","asset":{"type":"shape_art","parts":[{"shape":"sq","n":5},{"shape":"tri","n":3},{"shape":"cir","n":1}],"name":"배"},"options":[{"t":"겹쳐 놓인 네모 하나를 빠뜨리고 세었어요.","correct":true,"mis_target":"M1-2-u3-X06"},{"t":"같은 네모를 두 번 세었어요.","mis":"M1-2-u3-X07"},{"t":"색깔이 다른 네모는 세면 안 되니까요.","mis":"M1-2-u3-X01"}],"explanation":["그림에는 네모가 5개 있어요.","겹친 곳에 숨은 네모를 빠뜨려서 4개가 되었어요.","센 모양에 표시를 하면 빠뜨리지 않아요."],"seq":13}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_d#14','math',1,2,'u3','review','g1_2_math_u3_review_d','unit_review','M1-2-u3-C4',1,'mc','auto','시계를 보세요. 몇 시인가요?',ARRAY['M1-2-u3-X08','M1-2-u3-X09']::text[],true,'{"concept":"M1-2-u3-C4","difficulty":1,"kind":"mc","stem":"시계를 보세요. 몇 시인가요?","asset":{"type":"clock","h":5,"m":0},"options":[{"t":"5시","correct":true},{"t":"12시","mis":"M1-2-u3-X08"},{"t":"6시","mis":"M1-2-u3-X09"}],"explanation":["짧은바늘이 5를 가리키고, 긴바늘이 12를 가리켜요.","그래서 5시예요.","긴바늘이 12를 가리키면 「몇 시」예요."],"variant_rule":{"time":{"hours":[1,12],"half":"oclock"}},"seq":14}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_d#15','math',1,2,'u3','review','g1_2_math_u3_review_d','unit_review','M1-2-u3-C4',1,'sa','auto','시계를 보세요. 몇 시인가요? ‘○시’로 쓰세요.','{}'::text[],true,'{"concept":"M1-2-u3-C4","difficulty":1,"kind":"sa","stem":"시계를 보세요. 몇 시인가요? ‘○시’로 쓰세요.","asset":{"type":"clock","h":10,"m":0},"answer":["10시","10"],"explanation":["짧은바늘이 10을 가리켜요.","긴바늘은 12를 가리키니 10시예요.","짧은바늘부터 읽어요."],"variant_rule":{"time":{"hours":[1,12],"half":"oclock"}},"seq":15}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_d#16','math',1,2,'u3','review','g1_2_math_u3_review_d','unit_review','M1-2-u3-C4',2,'blank','auto','태오는 (        )에 잠자리에 들었어요. 시계를 보고 답하세요.',ARRAY['M1-2-u3-X08','M1-2-u3-X09']::text[],true,'{"concept":"M1-2-u3-C4","difficulty":2,"kind":"blank","stem":"태오는 (        )에 잠자리에 들었어요. 시계를 보고 답하세요.","asset":{"type":"clock","h":8,"m":0},"options":[{"t":"8시","correct":true},{"t":"12시","mis":"M1-2-u3-X08"},{"t":"9시","mis":"M1-2-u3-X09"}],"explanation":["짧은바늘이 8을 가리켜요.","긴바늘이 12에 있으니 8시예요.","짧은바늘이 지나온 수를 읽어요."],"variant_rule":{"time":{"hours":[1,12],"half":"oclock"}},"seq":16}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_d#17','math',1,2,'u3','review','g1_2_math_u3_review_d','unit_review','M1-2-u3-C4',3,'error','auto','친구가 이 시계를 보고 12시라고 읽었어요. 왜 틀렸을까요?',ARRAY['M1-2-u3-X08','M1-2-u3-X10']::text[],false,'{"concept":"M1-2-u3-C4","difficulty":3,"kind":"error","stem":"친구가 이 시계를 보고 12시라고 읽었어요. 왜 틀렸을까요?","asset":{"type":"clock","h":10,"m":0},"options":[{"t":"긴바늘이 가리키는 수를 시로 읽었어요.","correct":true,"mis_target":"M1-2-u3-X08"},{"t":"짧은바늘이 없어서 읽을 수 없어요.","mis":"M1-2-u3-X08"},{"t":"긴바늘이 6을 가리켜서 30분이에요.","mis":"M1-2-u3-X10"}],"explanation":["짧은바늘은 10을 가리키고 있어요.","긴바늘 12를 시로 읽어서 12시가 되었어요.","시는 언제나 짧은바늘이 알려 줘요."],"seq":17}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_d#18','math',1,2,'u3','review','g1_2_math_u3_review_d','unit_review','M1-2-u3-C5',1,'mc','auto','시계를 보세요. 몇 시 몇 분인가요?',ARRAY['M1-2-u3-X09','M1-2-u3-X10']::text[],true,'{"concept":"M1-2-u3-C5","difficulty":1,"kind":"mc","stem":"시계를 보세요. 몇 시 몇 분인가요?","asset":{"type":"clock","h":4,"m":30},"options":[{"t":"4시 30분","correct":true},{"t":"5시 30분","mis":"M1-2-u3-X09"},{"t":"4시 6분","mis":"M1-2-u3-X10"}],"explanation":["짧은바늘은 4와 5 사이, 긴바늘은 6을 가리켜요.","그래서 4시 30분이에요.","긴바늘이 6이면 30분이에요."],"variant_rule":{"time":{"hours":[1,12],"half":"half"}},"seq":18}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_d#19','math',1,2,'u3','review','g1_2_math_u3_review_d','unit_review','M1-2-u3-C5',2,'sa','auto','시계를 보세요. 몇 시 몇 분인가요? ‘○시 30분’으로 쓰세요.','{}'::text[],true,'{"concept":"M1-2-u3-C5","difficulty":2,"kind":"sa","stem":"시계를 보세요. 몇 시 몇 분인가요? ‘○시 30분’으로 쓰세요.","asset":{"type":"clock","h":11,"m":30},"answer":["11시 30분","11시30분"],"explanation":["짧은바늘이 11을 지나 12로 가는 중이에요.","긴바늘이 6이니 11시 30분이에요.","짧은바늘이 지나온 수를 읽어요."],"variant_rule":{"time":{"hours":[1,12],"half":"half"}},"seq":19}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_d#20','math',1,2,'u3','review','g1_2_math_u3_review_d','unit_review','M1-2-u3-C5',2,'ox','auto','이 시계는 11시 30분이에요.',ARRAY['M1-2-u3-X09']::text[],false,'{"concept":"M1-2-u3-C5","difficulty":2,"kind":"ox","stem":"이 시계는 11시 30분이에요.","asset":{"type":"clock","h":11,"m":30},"reason_options":[{"t":"짧은바늘은 11을 지났고 긴바늘은 반 바퀴를 돌았으니까","correct":true},{"t":"짧은바늘이 12에 가까우니 12시 30분이니까","mis":"M1-2-u3-X09"}],"answer":"O","explanation":["짧은바늘은 11과 12 사이에 있어요.","긴바늘은 6이니 11시 30분 맞아요.","짧은바늘은 지나온 수, 긴바늘 6은 30분이에요."],"seq":20}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_d#21','math',1,2,'u3','review','g1_2_math_u3_review_d','unit_review','M1-2-u3-C5',3,'error','auto','친구가 이 시계를 ‘5시 30분’이라고 읽었어요. 왜 틀렸을까요?',ARRAY['M1-2-u3-X09','M1-2-u3-X10','M1-2-u3-X08']::text[],true,'{"concept":"M1-2-u3-C5","difficulty":3,"kind":"error","stem":"친구가 이 시계를 ‘5시 30분’이라고 읽었어요. 왜 틀렸을까요?","asset":{"type":"clock","h":4,"m":30},"options":[{"t":"짧은바늘이 4와 5 사이인데 뒤의 수를 읽었어요.","correct":true,"mis_target":"M1-2-u3-X09"},{"t":"긴바늘이 6이라 30분이 아니에요.","mis":"M1-2-u3-X10"},{"t":"짧은바늘과 긴바늘을 바꿔 읽었어요.","mis":"M1-2-u3-X08"}],"explanation":["짧은바늘이 4를 지나 5로 가는 중이에요.","지나온 수를 읽어야 하니 4시 30분이에요.","가까워 보인다고 다음 수를 읽으면 안 돼요."],"variant_rule":{"time":{"hours":[1,12],"half":"half"}},"seq":21}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_d#22','math',1,2,'u3','review','g1_2_math_u3_review_d','unit_review','M1-2-u3-C6',2,'mc','auto','2시 30분을 시계에 나타내려면 긴바늘을 어디에 그려야 하나요?',ARRAY['M1-2-u3-X10','M1-2-u3-X08']::text[],false,'{"concept":"M1-2-u3-C6","difficulty":2,"kind":"mc","stem":"2시 30분을 시계에 나타내려면 긴바늘을 어디에 그려야 하나요?","asset":{"type":"clock","h":2,"m":30,"hands":"none"},"options":[{"t":"6","correct":true},{"t":"12","mis":"M1-2-u3-X10"},{"t":"2","mis":"M1-2-u3-X08"}],"explanation":["30분이면 긴바늘이 반 바퀴 돌아요.","반 바퀴는 6이에요.","짧은바늘은 2와 3 사이에 그려요."],"seq":22}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_d#23','math',1,2,'u3','review','g1_2_math_u3_review_d','unit_review','M1-2-u3-C6',3,'blank','auto','10시 30분을 나타내려면 짧은바늘을 10과 (        ) 사이에 그려요.',ARRAY['M1-2-u3-X09','M1-2-u3-X10']::text[],false,'{"concept":"M1-2-u3-C6","difficulty":3,"kind":"blank","stem":"10시 30분을 나타내려면 짧은바늘을 10과 (        ) 사이에 그려요.","asset":{"type":"clock","h":10,"m":30,"hands":"none"},"options":[{"t":"11","correct":true},{"t":"9","mis":"M1-2-u3-X09"},{"t":"6","mis":"M1-2-u3-X10"}],"explanation":["30분은 두 수의 가운데쯤이에요.","10시 30분이니 10과 11 사이예요.","6은 긴바늘이 가는 자리예요."],"seq":23}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_d#24','math',1,2,'u3','review','g1_2_math_u3_review_d','unit_review','M1-2-u3-C6',4,'mc','auto','민준는 5시에 축구를 시작했어요. 이때 시계의 두 바늘은 어떻게 놓여 있나요?',ARRAY['M1-2-u3-X10','M1-2-u3-X08']::text[],false,'{"concept":"M1-2-u3-C6","difficulty":4,"kind":"mc","stem":"민준는 5시에 축구를 시작했어요. 이때 시계의 두 바늘은 어떻게 놓여 있나요?","options":[{"t":"짧은바늘은 5, 긴바늘은 12","correct":true},{"t":"짧은바늘은 5와 6 사이, 긴바늘은 6","mis":"M1-2-u3-X10"},{"t":"짧은바늘은 12, 긴바늘은 5","mis":"M1-2-u3-X08"}],"explanation":["「몇 시」는 긴바늘이 12에 있어요.","짧은바늘이 5를 가리켜야 5시예요.","긴바늘이 6에 가면 5시 30분이 돼요."],"seq":24}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u3_review_d#25','math',1,2,'u3','review','g1_2_math_u3_review_d','unit_review','M1-2-u3-C6',4,'essay','teacher','저녁을 먹는 시각이 6시예요. 이 시각을 시계에 그린다면 짧은바늘과 긴바늘을 각각 어디에 그려야 하는지 쓰고, 그 까닭도 쓰세요.','{}'::text[],false,'{"concept":"M1-2-u3-C6","difficulty":4,"kind":"essay","stem":"저녁을 먹는 시각이 6시예요. 이 시각을 시계에 그린다면 짧은바늘과 긴바늘을 각각 어디에 그려야 하는지 쓰고, 그 까닭도 쓰세요.","asset":{"type":"clock","h":6,"m":0,"hands":"none"},"answer_guide":"짧은바늘 「6」 + 긴바늘 「12」 + 까닭(긴바늘이 12이면 몇 시 / 짧은바늘은 그 수를 가리킨다)이 함께 있으면 정답. 두 바늘 자리만 맞고 까닭이 없으면 반만 맞음. 두 바늘 길이를 바꿔 쓰면 틀림.","explanation":["긴바늘은 12에 그려요 — 「몇 시」니까요.","짧은바늘은 6에 그려요.","짧은바늘을 먼저 그리고 긴바늘을 길게 덧그려요."],"seq":25}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
